--
-- Name: _filter_literal(text, jsonb, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta._filter_literal(p_type text, p_value jsonb, p_cast text) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $_$
declare
  v_text text;
  v_m text[];
begin
  if p_type in ('dropdown', 'file', 'text') then
    if jsonb_typeof(p_value) is distinct from 'string' then
      raise exception 'expects a string';
    end if;
    return quote_literal(p_value #>> '{}') || '::' || p_cast;
  end if;
  v_text := p_value #>> '{}';
  if p_type = 'number' then
    if jsonb_typeof(p_value) not in ('number', 'string') or btrim(v_text) !~ '^-?\d+(\.\d+)?([eE][-+]?\d+)?$' then
      raise exception 'expects a number';
    end if;
    return quote_literal(btrim(v_text)) || '::numeric';
  elsif p_type = 'date' then
    v_m := regexp_match(coalesce(v_text, ''), '^(\d{4}-\d{2}-\d{2})(T00:00:00(\.0+)?Z)?$');
    if jsonb_typeof(p_value) is distinct from 'string' or v_m is null then
      raise exception 'expects a date';
    end if;
    perform v_m[1]::date;
    return quote_literal(v_m[1]) || '::date';
  elsif p_type = 'datetime' then
    if jsonb_typeof(p_value) is distinct from 'string' or v_text !~ '^\d{4}-\d{2}-\d{2}T' then
      raise exception 'expects a datetime';
    end if;
    return quote_literal(v_text::timestamptz::text) || '::timestamptz';
  end if;
  raise exception 'unsupported type %', p_type;
end $_$;


ALTER FUNCTION meta._filter_literal(p_type text, p_value jsonb, p_cast text) OWNER TO pc_migrator;

--
-- Name: _insert_options(text, jsonb); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta._insert_options(p_property_id text, p_options jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $_$
declare
  v_item jsonb;
  v_ord bigint;
begin
  if p_options is null or jsonb_typeof(p_options) <> 'array' then
    perform meta._fail('dropdown options must be an array of {"api_value", "label"}');
  end if;
  for v_item, v_ord in select e, o from jsonb_array_elements(p_options) with ordinality t (e, o) loop
    if v_item ->> 'api_value' is null or v_item ->> 'api_value' !~ '^[A-Za-z0-9._]{1,63}$' then
      perform meta._fail(format('option api_value "%s" must be 1 to 63 letters, digits, dots or underscores', v_item ->> 'api_value'));
    end if;
    if char_length(coalesce(v_item ->> 'label', '')) not between 1 and 63 then
      perform meta._fail(format('option label for "%s" must be 1 to 63 characters', v_item ->> 'api_value'));
    end if;
    if exists (select 1 from meta.pc_0003 where property_id = p_property_id
        and (api_value = v_item ->> 'api_value' or lower(label) = lower(v_item ->> 'label'))) then
      perform meta._fail(format('option "%s" / "%s" already exists on this property', v_item ->> 'api_value', v_item ->> 'label'), '23505');
    end if;
    insert into meta.pc_0003 (property_id, api_value, label, description, display_order)
    values (p_property_id, v_item ->> 'api_value', v_item ->> 'label', v_item ->> 'description',
      coalesce((v_item ->> 'display_order')::integer,
        (select coalesce(max(display_order), 0) + 1 from meta.pc_0003 where property_id = p_property_id)));
  end loop;
end $_$;


ALTER FUNCTION meta._insert_options(p_property_id text, p_options jsonb) OWNER TO pc_migrator;

--
-- Name: _line_accepted_quote(text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta._line_accepted_quote(p_line text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  select q.pc_0022_id
  from crm.associations_both a join crm.pc_0022 q on q.pc_0022_id = a.other_record_id
  where a.object_type_id = 'pc_0020' and a.record_id = p_line and a.other_object_type_id = 'pc_0022'
    and q.status[1] = 'accepted' and q.record_status not in ('deleted', 'merged')
  limit 1
$$;


ALTER FUNCTION meta._line_accepted_quote(p_line text) OWNER TO pc_migrator;

--
-- Name: _line_other_link(text, boolean, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta._line_other_link(p_line text, p_products boolean, p_other text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_link record;
  v_status text;
begin
  for v_link in
    select other_object_type_id as t, other_record_id as id from crm.associations_both
    where object_type_id = 'pc_0020' and record_id = p_line and other_record_id <> p_other
      and (other_object_type_id = 'pc_0021') = p_products
  loop
    execute format('select record_status from crm.%I where %I = $1', v_link.t, v_link.t || '_id') into v_status using v_link.id;
    if v_status is distinct from 'merged' then
      return (select api_name from meta.pc_0001 where object_type_id = v_link.t) || ' ' || v_link.id;
    end if;
  end loop;
  return null;
end $_$;


ALTER FUNCTION meta._line_other_link(p_line text, p_products boolean, p_other text) OWNER TO pc_migrator;

