--
-- Name: pc_0001; Type: TABLE; Schema: meta; Owner: pc_migrator
--

CREATE TABLE meta.pc_0001 (
    pc_0001_id text DEFAULT meta.hex_id('meta.pc_0001_seq'::regclass) NOT NULL,
    object_type_id text NOT NULL,
    api_name text NOT NULL,
    label_singular text NOT NULL,
    label_plural text NOT NULL,
    kind text NOT NULL,
    schema_name text NOT NULL,
    description text,
    record_status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by text,
    row_created_at timestamp with time zone DEFAULT now() NOT NULL,
    row_updated_at timestamp with time zone DEFAULT now() NOT NULL,
    search_properties text[] DEFAULT '{name}'::text[] NOT NULL,
    aliases text[] DEFAULT '{}'::text[] NOT NULL,
    CONSTRAINT pc_0001_aliases_check CHECK ((cardinality(aliases) <= 10)),
    CONSTRAINT pc_0001_api_name_check CHECK ((api_name ~ '^[a-z][a-z0-9_]{0,62}$'::text)),
    CONSTRAINT pc_0001_kind_check CHECK ((kind = ANY (ARRAY['system'::text, 'native'::text, 'custom'::text]))),
    CONSTRAINT pc_0001_label_plural_check CHECK (((char_length(label_plural) >= 1) AND (char_length(label_plural) <= 63))),
    CONSTRAINT pc_0001_label_singular_check CHECK (((char_length(label_singular) >= 1) AND (char_length(label_singular) <= 63))),
    CONSTRAINT pc_0001_object_type_id_check CHECK ((object_type_id ~ '^pc_[0-9]{4}$'::text)),
    CONSTRAINT pc_0001_pc_0001_id_check CHECK ((pc_0001_id ~ '^[0-9a-f]{10}$'::text)),
    CONSTRAINT pc_0001_record_status_check CHECK ((record_status = ANY (ARRAY['active'::text, 'archived'::text]))),
    CONSTRAINT pc_0001_schema_name_check CHECK ((schema_name = ANY (ARRAY['meta'::text, 'crm'::text])))
);


