--
-- Name: _sync_user_options_for_property(text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta._sync_user_options_for_property(p_property_id text) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_user record;
  v_label text;
  v_changed boolean := false;
begin
  for v_user in
    select pc_0000_id as id, coalesce(nullif(btrim(name), ''), pc_0000_id) as name from crm.pc_0000
    where record_status = 'active' and not coalesce(status, '{}') @> '{deactivated}'
  loop
    v_label := left(v_user.name, 63);
    if exists (select 1 from meta.pc_0003 where property_id = p_property_id and lower(label) = lower(v_label) and api_value <> v_user.id) then
      v_label := left(v_user.name, 50) || ' (' || v_user.id || ')';
    end if;
    if exists (select 1 from meta.pc_0003 where property_id = p_property_id and api_value = v_user.id) then
      update meta.pc_0003 set label = v_label, record_status = 'active'
      where property_id = p_property_id and api_value = v_user.id and (label <> v_label or record_status <> 'active');
      v_changed := v_changed or found;
    else
      insert into meta.pc_0003 (property_id, api_value, label, display_order)
      values (p_property_id, v_user.id, v_label, (select coalesce(max(display_order), 0) + 1 from meta.pc_0003 where property_id = p_property_id));
      v_changed := true;
    end if;
  end loop;

  update meta.pc_0003 o set record_status = 'archived'
  from crm.pc_0000 u
  where o.property_id = p_property_id and o.api_value = u.pc_0000_id and o.record_status = 'active'
    and (u.record_status <> 'active' or coalesce(u.status, '{}') @> '{deactivated}');
  v_changed := v_changed or found;

  if v_changed then
    perform meta._apply_property_rules(p_property_id, false);
    -- logging also tells API registry caches to reload
    perform meta._log_change('sync_user_options', (select object_type_id from meta.pc_0002 where pc_0002_id = p_property_id), p_property_id, '{}'::jsonb);
  end if;
end $$;


ALTER FUNCTION meta._sync_user_options_for_property(p_property_id text) OWNER TO pc_migrator;

--
-- Name: _tg_base_currency_code(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta._tg_base_currency_code() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_prop record;
begin
  for v_prop in
    update meta.pc_0002 set options = options || jsonb_build_object('currency_code', new.code)
    where type = 'calculation' and record_status = 'active' and calc_sql ~* 'currency_to_base\s*\('
      and options ->> 'format' = 'currency' and options ->> 'currency_code' is distinct from new.code
    returning pc_0002_id, object_type_id, api_name, options
  loop
    perform meta._log_change('update_property', v_prop.object_type_id, v_prop.pc_0002_id,
      jsonb_build_object('api_name', v_prop.api_name, 'options', v_prop.options, 'reason', 'base currency changed'));
  end loop;
  return null;
end $$;


ALTER FUNCTION meta._tg_base_currency_code() OWNER TO pc_migrator;

--
-- Name: _tg_currency_base(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta._tg_currency_base() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
begin
  if new.is_base then
    if new.record_status <> 'active' then
      raise exception 'the base currency cannot be archived; pick another base currency first' using errcode = '22023';
    end if;
    new.rate_to_base := 1;
    new.rate_manual := false;
  end if;
  new.code := upper(new.code);
  return new;
end $$;


ALTER FUNCTION meta._tg_currency_base() OWNER TO pc_migrator;

