--
-- Name: _validate_options(text, jsonb); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta._validate_options(p_type text, p_options jsonb) RETURNS void
    LANGUAGE plpgsql
    AS $_$
declare
  v_spec jsonb;
  v_key text;
  v_value jsonb;
  v_kind text;
  v_ok boolean;
begin
  v_spec := case p_type
    when 'text' then '{"single_line":"boolean","display":"display","regex":"regex","regex_scope":"regex_scope","json_only":"boolean","unique":"boolean","case_insensitive":"boolean"}'
    when 'number' then '{"format":"number_format","prefix":"string","suffix":"string","decimals":"decimals","min":"number","max":"number","currency_code":"currency","currency_property":"string"}'
    when 'dropdown' then '{"single_value":"boolean","allow_form_add":"boolean","allow_user_add":"boolean","auto_append_users":"boolean","default_value":"string","parent_property":"string","color_display":"color_display"}'
    when 'date' then '{}'
    when 'datetime' then '{"timezone":"timezone"}'
    when 'file' then '{"max_files":"positive_int"}'
    when 'calculation' then '{"display":"display","format":"number_format","prefix":"string","suffix":"string","decimals":"decimals","timezone":"timezone","currency_code":"currency"}'
    else '{}'
  end::jsonb;
  for v_key, v_value in select * from jsonb_each(p_options) loop
    v_kind := v_spec ->> v_key;
    if v_kind is null then
      perform meta._fail(format('option "%s" is not allowed for %s properties (allowed: %s)', v_key, p_type,
        coalesce((select string_agg(k, ', ') from jsonb_object_keys(v_spec) k), 'none')));
    end if;
    v_ok := case v_kind
      when 'boolean' then jsonb_typeof(v_value) = 'boolean'
      when 'string' then jsonb_typeof(v_value) = 'string' and char_length(v_value #>> '{}') <= 63
      when 'number' then jsonb_typeof(v_value) = 'number'
      when 'regex' then jsonb_typeof(v_value) = 'string'
      when 'display' then v_value #>> '{}' in ('plain', 'url', 'markdown', 'json', 'html', 'phone', 'code')
      when 'regex_scope' then v_value #>> '{}' in ('all', 'ui')
      when 'number_format' then v_value #>> '{}' in ('formatted', 'unformatted', 'currency', 'percentage')
      when 'currency' then exists (select 1 from meta.pc_0007 where code = v_value #>> '{}')
      when 'timezone' then exists (select 1 from pg_timezone_names where name = v_value #>> '{}')
      when 'decimals' then jsonb_typeof(v_value) = 'number' and (v_value #>> '{}') ~ '^([0-9]|10)$'
      when 'color_display' then v_value #>> '{}' in ('none', 'dot', 'pill')
      when 'positive_int' then jsonb_typeof(v_value) = 'number' and (v_value #>> '{}') ~ '^[1-9][0-9]{0,5}$'
      else false
    end;
    if not coalesce(v_ok, false) then
      perform meta._fail(format('option "%s" has an invalid value: %s', v_key, v_value));
    end if;
    if v_kind = 'regex' then
      begin
        perform '' ~ (v_value #>> '{}');
      exception when others then
        perform meta._fail(format('regex is invalid: %s', sqlerrm));
      end;
    end if;
  end loop;
  if p_options ? 'min' and p_options ? 'max' and (p_options ->> 'min')::numeric > (p_options ->> 'max')::numeric then
    perform meta._fail('min cannot be greater than max');
  end if;
  if p_options ? 'regex_scope' and not p_options ? 'regex' then
    perform meta._fail('regex_scope requires regex');
  end if;
  if p_options ->> 'color_display' = 'dot' and not coalesce((p_options ->> 'single_value')::boolean, false) then
    perform meta._fail('color_display dot needs single_value; multi-choice dropdowns use none or pill');
  end if;
end $_$;


ALTER FUNCTION meta._validate_options(p_type text, p_options jsonb) OWNER TO pc_migrator;

--
-- Name: _validate_property_name(text, text, text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta._validate_property_name(p_object_type_id text, p_api_name text, p_label text, p_exclude_id text) RETURNS void
    LANGUAGE plpgsql
    AS $_$
begin
  if p_api_name is not null then
    if p_api_name !~ '^[A-Za-z][A-Za-z0-9._]{0,62}$' then
      perform meta._fail('api_name must be letters, digits, dots and underscores, start with a letter, max 63 characters');
    end if;
    if lower(p_api_name) in ('id', 'object_type_id', 'name', 'created_at', 'updated_at', 'merged_ids', 'merged_into_id',
        'record_status', 'created_by', 'updated_by')
      or lower(p_api_name) ~ '^(pc_|row_)' or p_api_name ~ '__' then
      perform meta._fail(format('api_name "%s" is reserved (also reserved: pc_ and row_ prefixes, and double underscores)', p_api_name));
    end if;
    if exists (select 1 from meta.pc_0002 where object_type_id = p_object_type_id and lower(api_name) = lower(p_api_name)
        and pc_0002_id is distinct from p_exclude_id) then
      perform meta._fail(format('a property with api_name "%s" already exists on %s', p_api_name, p_object_type_id), '23505');
    end if;
  end if;
  if p_label is not null then
    if char_length(p_label) not between 1 and 63 then
      perform meta._fail('label must be 1 to 63 characters');
    end if;
    if exists (select 1 from meta.pc_0002 where object_type_id = p_object_type_id and lower(label) = lower(p_label)
        and pc_0002_id is distinct from p_exclude_id) then
      perform meta._fail(format('a property labeled "%s" already exists on %s', p_label, p_object_type_id), '23505');
    end if;
  end if;
end $_$;


ALTER FUNCTION meta._validate_property_name(p_object_type_id text, p_api_name text, p_label text, p_exclude_id text) OWNER TO pc_migrator;

--
-- Name: _view_function_allowed(oid); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta._view_function_allowed(p_oid oid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where p.oid = p_oid and (
      (n.nspname = 'pg_catalog' and p.prokind in ('a', 'w'))
      or (n.nspname in ('pg_catalog', 'public') and (
            exists (select 1 from pg_operator o where o.oprcode = p.oid)
            or exists (select 1 from pg_cast c where c.castfunc = p.oid)))
      or (n.nspname = 'pg_catalog' and p.prokind = 'f' and p.proname = any (array['abs', 'ceil', 'ceiling', 'floor', 'round', 'trunc', 'sign', 'mod', 'div', 'power', 'pow', 'sqrt', 'cbrt', 'exp', 'ln', 'log', 'log10', 'pi', 'random', 'width_bucket', 'scale', 'length', 'char_length', 'character_length', 'octet_length', 'lower', 'upper', 'initcap', 'btrim', 'ltrim', 'rtrim', 'substr', 'substring', 'left', 'right', 'replace', 'translate', 'concat', 'concat_ws', 'split_part', 'strpos', 'position', 'lpad', 'rpad', 'repeat', 'reverse', 'format', 'starts_with', 'regexp_replace', 'regexp_match', 'regexp_matches', 'regexp_split_to_array', 'regexp_like', 'string_to_array', 'array_to_string', 'md5', 'to_hex', 'to_char', 'to_number', 'to_date', 'to_timestamp', 'now', 'clock_timestamp', 'statement_timestamp', 'transaction_timestamp', 'date_trunc', 'date_part', 'extract', 'date_bin', 'age', 'isfinite', 'make_date', 'make_time', 'make_timestamp', 'make_timestamptz', 'make_interval', 'justify_days', 'justify_hours', 'justify_interval', 'timezone', 'array_length', 'array_upper', 'array_lower', 'array_ndims', 'cardinality', 'array_position', 'array_positions', 'array_remove', 'array_replace', 'array_append', 'array_prepend', 'array_cat', 'unnest', 'generate_series', 'generate_subscripts', 'to_json', 'to_jsonb', 'row_to_json', 'json_build_object', 'jsonb_build_object', 'json_build_array', 'jsonb_build_array', 'json_object', 'jsonb_object', 'json_array_elements', 'jsonb_array_elements', 'json_array_elements_text', 'jsonb_array_elements_text', 'json_each', 'jsonb_each', 'json_each_text', 'jsonb_each_text', 'json_object_keys', 'jsonb_object_keys', 'json_typeof', 'jsonb_typeof', 'json_array_length', 'jsonb_array_length', 'json_extract_path', 'jsonb_extract_path', 'json_extract_path_text', 'jsonb_extract_path_text', 'jsonb_strip_nulls', 'jsonb_pretty', 'num_nulls', 'num_nonnulls']))
      or (n.nspname = 'public' and p.proname in ('similarity', 'word_similarity', 'strict_word_similarity'))
      or (n.nspname = 'view_data' and p.proname in ('currency_rate', 'convert_currency'))
    )
  )
$$;


ALTER FUNCTION meta._view_function_allowed(p_oid oid) OWNER TO pc_migrator;

