--
-- Name: add_option(text, text, text, text, integer, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.add_option(p_object text, p_api_name text, p_api_value text, p_label text, p_display_order integer DEFAULT NULL::integer, p_description text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_prop meta.pc_0002 := meta._resolve_property(v_obj.object_type_id, p_api_name);
  v_id text;
begin
  if v_prop.type <> 'dropdown' then
    perform meta._fail(format('"%s" is not a dropdown', p_api_name));
  end if;
  perform meta._insert_options(v_prop.pc_0002_id, jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
    'api_value', p_api_value, 'label', p_label, 'display_order', p_display_order, 'description', p_description))));
  select pc_0003_id into v_id from meta.pc_0003 where property_id = v_prop.pc_0002_id and api_value = p_api_value;
  perform meta._apply_property_rules(v_prop.pc_0002_id, false);
  perform meta._log_change('add_option', v_obj.object_type_id, v_prop.pc_0002_id,
    jsonb_build_object('api_name', v_prop.api_name, 'api_value', p_api_value, 'label', p_label));
  return v_id;
end $$;


ALTER FUNCTION meta.add_option(p_object text, p_api_name text, p_api_value text, p_label text, p_display_order integer, p_description text) OWNER TO pc_migrator;

--
-- Name: analyze_view_query(text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.analyze_view_query(p_sql text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'view_data', 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_probe text := '_view_probe_' || pg_backend_pid();
  v_view oid;
  v_rec record;
  v_objects text[] := '{}';
  v_columns jsonb := '[]';
  v_output jsonb;
  v_code text;
begin
  begin
    perform meta._check_sql_fragment(p_sql);
  exception when others then
    perform meta._fail(replace(sqlerrm, 'calculation', 'query'));
  end;
  if p_sql !~* '^\s*\(*\s*(select|with)\s' then
    perform meta._fail('a view query must be a single SELECT (or WITH ... SELECT)');
  end if;

  execute format('drop view if exists meta.%I', v_probe);
  begin
    execute format('create view meta.%I as select * from (%s) q', v_probe, p_sql);
  exception when others then
    perform meta._fail(format('query is invalid: %s', sqlerrm));
  end;
  v_view := format('meta.%I', v_probe)::regclass;

  for v_rec in
    select distinct p.oid, pn.nspname as proschema, p.proname
    from pg_rewrite rw
    cross join lateral regexp_matches(rw.ev_action::text, ':(?:funcid|opfuncid|aggfnoid|winfnoid) (\d+)', 'g') m
    join pg_proc p on p.oid = m[1]::oid
    join pg_namespace pn on pn.oid = p.pronamespace
    where rw.ev_class = v_view
  loop
    if not meta._view_function_allowed(v_rec.oid) then
      execute format('drop view meta.%I', v_probe);
      perform meta._fail(format('view queries may not call %s.%s() (see view_guide topic sql for the functions allowed)', v_rec.proschema, v_rec.proname));
    end if;
  end loop;

  for v_rec in
    select distinct n.nspname, c.relname
    from pg_rewrite rw
    cross join lateral regexp_matches(rw.ev_action::text, ':relid (\d+)', 'g') m
    join pg_class c on c.oid = m[1]::oid
    join pg_namespace n on n.oid = c.relnamespace
    where rw.ev_class = v_view and c.oid <> v_view
  loop
    if v_rec.nspname <> 'view_data' then
      execute format('drop view meta.%I', v_probe);
      perform meta._fail(format('view queries may only read view_data (not %s.%s)', v_rec.nspname, v_rec.relname));
    end if;
    select object_type_id into v_code from meta.pc_0001 where api_name = v_rec.relname and schema_name = 'crm' and object_type_id <> 'pc_0005';
    if v_code is not null and not v_code = any (v_objects) then
      v_objects := v_objects || v_code;
    end if;
  end loop;

  for v_rec in
    select distinct c.relname, a.attname
    from pg_depend d
    join pg_rewrite rw on rw.oid = d.objid and d.classid = 'pg_rewrite'::regclass
    join pg_class c on d.refclassid = 'pg_class'::regclass and c.oid = d.refobjid
    join pg_namespace n on n.oid = c.relnamespace and n.nspname = 'view_data'
    join pg_attribute a on a.attrelid = c.oid and a.attnum = d.refobjsubid and d.refobjsubid > 0
    where rw.ev_class = v_view
  loop
    select object_type_id into v_code from meta.pc_0001 where api_name = v_rec.relname and schema_name = 'crm' and object_type_id <> 'pc_0005';
    if v_code is not null then
      v_columns := v_columns || jsonb_build_object('object', v_code, 'column', regexp_replace(v_rec.attname, '__label$', ''));
    end if;
  end loop;

  select coalesce(jsonb_agg(jsonb_build_object('name', attname, 'type', format_type(atttypid, atttypmod)) order by attnum), '[]')
  into v_output from pg_attribute where attrelid = v_view and attnum > 0 and not attisdropped;
  execute format('drop view meta.%I', v_probe);

  select coalesce(jsonb_agg(distinct c), '[]') into v_columns from jsonb_array_elements(v_columns) c;
  return jsonb_build_object('objects', to_jsonb(v_objects), 'columns', v_columns, 'output', v_output);
end $_$;


ALTER FUNCTION meta.analyze_view_query(p_sql text) OWNER TO pc_migrator;

--
-- Name: archive_property(text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.archive_property(p_object text, p_api_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_prop meta.pc_0002 := meta._resolve_property(v_obj.object_type_id, p_api_name);
  v_users text;
begin
  if v_prop.is_base then
    perform meta._fail('base properties cannot be archived');
  end if;
  select string_agg(distinct p.object_type_id || '.' || p.api_name, ', ') into v_users
  from meta.calc_dependencies d join meta.pc_0002 p on p.pc_0002_id = d.property_id
  where d.rel_object = v_obj.object_type_id and lower(d.column_name) = lower(v_prop.api_name)
    and p.record_status = 'active' and p.pc_0002_id <> v_prop.pc_0002_id;
  if v_users is not null then
    perform meta._fail(format('blocked: calculations read "%s": %s', v_prop.api_name, v_users), '55006');
  end if;
  update meta.pc_0002 set record_status = 'archived' where pc_0002_id = v_prop.pc_0002_id;
  if v_prop.type <> 'calculation' then
    execute format('revoke insert (%1$I), update (%1$I) on crm.%2$I from pc_api', v_prop.api_name, v_obj.object_type_id);
  end if;
  perform meta._refresh_views(v_obj.object_type_id);
  perform meta._log_change('archive_property', v_obj.object_type_id, v_prop.pc_0002_id, jsonb_build_object('api_name', v_prop.api_name));
end $_$;


ALTER FUNCTION meta.archive_property(p_object text, p_api_name text) OWNER TO pc_migrator;

--
-- Name: associate(text, text, text, text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.associate(p_from_object text, p_from_id text, p_to_object text, p_to_id text, p_label_id text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_a text := (meta._resolve_record_object(p_from_object)).object_type_id;
  v_b text := (meta._resolve_record_object(p_to_object)).object_type_id;
  v_label meta.pc_0004;
  v_from_type text;
  v_from_id text;
  v_to_type text;
  v_to_id text;
  v_id text;
begin
  if p_label_id is null then
    -- resolve first: a label created here is not visible to the same statement's snapshot
    p_label_id := meta._default_label(v_a, v_b);
    select * into v_label from meta.pc_0004 where pc_0004_id = p_label_id;
  else
    select * into v_label from meta.pc_0004 where pc_0004_id = p_label_id;
    if not found then
      perform meta._fail(format('unknown association label %s', p_label_id), 'P0002');
    end if;
  end if;
  if v_label.from_object_type = v_a and v_label.to_object_type = v_b then
    v_from_type := v_a; v_from_id := p_from_id; v_to_type := v_b; v_to_id := p_to_id;
  elsif v_label.from_object_type = v_b and v_label.to_object_type = v_a then
    v_from_type := v_b; v_from_id := p_to_id; v_to_type := v_a; v_to_id := p_from_id;
  else
    perform meta._fail('that association label does not connect these objects');
  end if;
  if v_label.is_symmetric and v_from_id > v_to_id then
    select v_to_id, v_from_id into v_from_id, v_to_id;
  end if;
  insert into crm.pc_0005 (label_id, from_object_type, from_id, to_object_type, to_id)
  values (v_label.pc_0004_id, v_from_type, v_from_id, v_to_type, v_to_id)
  on conflict (label_id, from_id, to_id) do nothing
  returning pc_0005_id into v_id;
  if v_id is null then
    select pc_0005_id into v_id from crm.pc_0005 where label_id = v_label.pc_0004_id and from_id = v_from_id and to_id = v_to_id;
  end if;
  return v_id;
end $$;


ALTER FUNCTION meta.associate(p_from_object text, p_from_id text, p_to_object text, p_to_id text, p_label_id text) OWNER TO pc_migrator;

--
-- Name: association_allowed(text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.association_allowed(p_a text, p_b text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select case
    when 'pc_0034' in (p_a, p_b) then least(p_a, p_b) <> greatest(p_a, p_b)
      and (case when p_a = 'pc_0034' then p_b else p_a end) in ('pc_0030', 'pc_0031', 'pc_0032', 'pc_0033', 'pc_0053', 'pc_0061', 'pc_0063')
    when least(p_a, p_b) = 'pc_0022' and greatest(p_a, p_b) = 'pc_0053' then false
    when 'pc_0000' in (p_a, p_b) then least(p_a, p_b) = 'pc_0000' and greatest(p_a, p_b) = 'pc_0006'
    when 'pc_0051' in (p_a, p_b) then false
    when 'pc_0055' in (p_a, p_b) then false
    when p_a = 'pc_0056' then p_b in ('pc_0010', 'pc_0011', 'pc_0060', 'pc_0061')
    when p_b = 'pc_0056' then p_a in ('pc_0010', 'pc_0011', 'pc_0060', 'pc_0061')
    when p_a = 'pc_0057' then p_b = 'pc_0022'
    when p_b = 'pc_0057' then p_a = 'pc_0022'
    when p_a = 'pc_0020' then p_b = 'pc_0021' or meta.is_line_parent(p_b)
    when p_b = 'pc_0020' then p_a = 'pc_0021' or meta.is_line_parent(p_a)
    when p_a in ('pc_0030', 'pc_0031', 'pc_0032', 'pc_0033') then p_b not in (
      'pc_0030', 'pc_0031', 'pc_0032', 'pc_0033', 'pc_0020', 'pc_0052', 'pc_0060', 'pc_0061',
      'pc_0062', 'pc_0063', 'pc_0025', 'pc_0022', 'pc_0024', 'pc_0023')
    when p_b in ('pc_0030', 'pc_0031', 'pc_0032', 'pc_0033') then p_a not in (
      'pc_0020', 'pc_0052', 'pc_0060', 'pc_0061', 'pc_0062', 'pc_0063', 'pc_0025', 'pc_0022', 'pc_0024', 'pc_0023')
    else true
  end
$$;


ALTER FUNCTION meta.association_allowed(p_a text, p_b text) OWNER TO pc_migrator;

--
-- Name: association_system_only(text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.association_system_only(p_a text, p_b text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select (least(p_a, p_b) = 'pc_0052' and greatest(p_a, p_b) = 'pc_0053')
      or (least(p_a, p_b) = 'pc_0030' and greatest(p_a, p_b) = 'pc_0054')
      or ('pc_0034' in (p_a, p_b))
$$;


ALTER FUNCTION meta.association_system_only(p_a text, p_b text) OWNER TO pc_migrator;

--
-- Name: compile_filter_groups(text, jsonb, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.compile_filter_groups(p_object_type_id text, p_groups jsonb, p_alias text) RETURNS text
    LANGUAGE plpgsql STABLE
    AS $$
declare
  v_group jsonb;
  v_filter jsonb;
  v_ands text[];
  v_ors text[] := '{}';
begin
  if jsonb_typeof(p_groups) is distinct from 'array' or jsonb_array_length(p_groups) = 0 or jsonb_array_length(p_groups) > 5 then
    return null;
  end if;
  for v_group in select * from jsonb_array_elements(p_groups) loop
    if jsonb_typeof(v_group -> 'filters') is distinct from 'array'
      or jsonb_array_length(v_group -> 'filters') not between 1 and 10 then
      return null;
    end if;
    v_ands := '{}';
    for v_filter in select * from jsonb_array_elements(v_group -> 'filters') loop
      v_ands := v_ands || meta._compile_filter(p_object_type_id, v_filter, p_alias);
    end loop;
    v_ors := v_ors || ('(' || array_to_string(v_ands, ' and ') || ')');
  end loop;
  return '(' || array_to_string(v_ors, ' or ') || ')';
exception when others then
  return null;
end $$;


ALTER FUNCTION meta.compile_filter_groups(p_object_type_id text, p_groups jsonb, p_alias text) OWNER TO pc_migrator;

--
-- Name: copy_lines(text, text, text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.copy_lines(p_from_object text, p_from_id text, p_to_object text, p_to_id text) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_from meta.pc_0001 := meta._resolve_record_object(p_from_object);
  v_to meta.pc_0001 := meta._resolve_record_object(p_to_object);
  v_cols text;
  v_line text;
  v_new text;
  v_out text[] := '{}';
  v_status text;
begin
  if not meta.is_line_parent(v_from.object_type_id) or not meta.is_line_parent(v_to.object_type_id) then
    perform meta._fail(format('%s and %s do not both have line items', v_from.api_name, v_to.api_name));
  end if;
  if v_from.object_type_id = v_to.object_type_id and p_from_id = p_to_id then
    perform meta._fail('cannot copy lines onto the same record');
  end if;
  execute format('select record_status from crm.%I where %I = $1', v_to.object_type_id, v_to.object_type_id || '_id') into v_status using p_to_id;
  if v_status is distinct from 'active' then
    perform meta._fail(format('record %s/%s is not active', v_to.api_name, p_to_id), 'P0002');
  end if;
  select string_agg(quote_ident(api_name), ', ' order by pc_0002_id) into v_cols
  from meta.pc_0002
  where object_type_id = 'pc_0020' and record_status = 'active' and not is_base and not read_only
    and type <> 'calculation' and coalesce((options ->> 'unique')::boolean, false) = false;
  v_cols := 'name' || coalesce(', ' || v_cols, '');

  for v_line in
    select l.pc_0020_id from crm.associations_both a join crm.pc_0020 l on l.pc_0020_id = a.other_record_id
    where a.object_type_id = v_from.object_type_id and a.record_id = p_from_id
      and a.other_object_type_id = 'pc_0020' and l.record_status = 'active'
    order by l.created_at, l.pc_0020_id
  loop
    execute format('insert into crm.pc_0020 (%1$s) select %1$s from crm.pc_0020 where pc_0020_id = $1 returning pc_0020_id', v_cols)
      into v_new using v_line;
    perform meta.associate('pc_0020', v_new, 'pc_0021', a.other_record_id, a.label_id)
    from crm.associations_both a
    where a.object_type_id = 'pc_0020' and a.record_id = v_line and a.other_object_type_id = 'pc_0021';
    perform meta.associate('pc_0020', v_new, v_to.object_type_id, p_to_id);
    v_out := v_out || v_new;
  end loop;
  return v_out;
end $_$;


ALTER FUNCTION meta.copy_lines(p_from_object text, p_from_id text, p_to_object text, p_to_id text) OWNER TO pc_migrator;

--
-- Name: create_association_label(text, text, text, text, boolean, integer, integer, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.create_association_label(p_from_object text, p_to_object text, p_label text, p_inverse_label text DEFAULT NULL::text, p_is_symmetric boolean DEFAULT false, p_max_to_per_from integer DEFAULT NULL::integer, p_max_from_per_to integer DEFAULT NULL::integer, p_category text DEFAULT 'custom'::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_from meta.pc_0001 := meta._resolve_record_object(p_from_object);
  v_to meta.pc_0001 := meta._resolve_record_object(p_to_object);
  v_id text;
begin
  if p_label is null or char_length(p_label) not between 1 and 63 then
    perform meta._fail('label must be 1 to 63 characters');
  end if;
  if p_is_symmetric and v_from.object_type_id <> v_to.object_type_id then
    perform meta._fail('symmetric labels must connect an object to itself');
  end if;
  if exists (select 1 from meta.pc_0004 where from_object_type = v_from.object_type_id and to_object_type = v_to.object_type_id and lower(label) = lower(p_label)) then
    perform meta._fail(format('label "%s" already exists for %s -> %s', p_label, v_from.api_name, v_to.api_name), '23505');
  end if;
  insert into meta.pc_0004 (from_object_type, to_object_type, label, inverse_label, is_symmetric, category, max_to_per_from, max_from_per_to)
  values (v_from.object_type_id, v_to.object_type_id, p_label, case when p_is_symmetric then null else p_inverse_label end,
    p_is_symmetric, p_category, p_max_to_per_from, p_max_from_per_to)
  returning pc_0004_id into v_id;
  perform meta._log_change('create_association_label', v_from.object_type_id, null,
    jsonb_build_object('label_id', v_id, 'from', v_from.object_type_id, 'to', v_to.object_type_id, 'label', p_label,
      'inverse_label', p_inverse_label, 'is_symmetric', p_is_symmetric));
  return v_id;
end $$;


ALTER FUNCTION meta.create_association_label(p_from_object text, p_to_object text, p_label text, p_inverse_label text, p_is_symmetric boolean, p_max_to_per_from integer, p_max_from_per_to integer, p_category text) OWNER TO pc_migrator;

--
-- Name: create_integration_table(text, jsonb, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.create_integration_table(p_name text, p_columns jsonb, p_primary_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_col jsonb;
  v_defs text[] := '{}';
  v_stmts text[];
  v_stmt text;
begin
  if p_name !~ '^[a-z][a-z0-9_]{0,62}$' then
    perform meta._fail('integration table name must be lowercase letters, digits and underscores, start with a letter, max 63');
  end if;
  if to_regclass(format('integrations.%I', p_name)) is not null then
    perform meta._fail(format('integrations.%s already exists', p_name), '23505');
  end if;
  if jsonb_typeof(p_columns) <> 'array' or jsonb_array_length(p_columns) = 0 then
    perform meta._fail('columns must be a non-empty array');
  end if;
  for v_col in select * from jsonb_array_elements(p_columns) loop
    if v_col ->> 'name' !~ '^[a-z][a-z0-9_]{0,62}$' or v_col ->> 'name' in ('row_created_at', 'row_updated_at') then
      perform meta._fail(format('invalid column name "%s"', v_col ->> 'name'));
    end if;
    if v_col ->> 'type' not in ('text', 'numeric', 'bigint', 'boolean', 'date', 'timestamptz', 'jsonb') then
      perform meta._fail(format('invalid column type "%s"', v_col ->> 'type'));
    end if;
    v_defs := v_defs || format('%I %s', v_col ->> 'name', v_col ->> 'type');
  end loop;
  if not exists (select 1 from jsonb_array_elements(p_columns) c where c ->> 'name' = p_primary_key) then
    perform meta._fail('primary_key must be one of the columns');
  end if;
  v_stmts := array[
    format('create table integrations.%I (%s, row_created_at timestamptz not null default now(), row_updated_at timestamptz not null default now(), primary key (%I))',
      p_name, array_to_string(v_defs, ', '), p_primary_key),
    format('create trigger touch before update on integrations.%I for each row execute function meta.tg_touch_row()', p_name),
    format('create index %I on integrations.%I (row_updated_at)', p_name || '_row_updated_at_idx', p_name),
    format('grant select on integrations.%I to pc_api, pc_reader', p_name)
  ];
  foreach v_stmt in array v_stmts loop
    execute v_stmt;
  end loop;
  perform meta._log_change('create_integration_table', null, null, jsonb_build_object('table', p_name, 'columns', p_columns, 'primary_key', p_primary_key), v_stmts);
end $_$;


ALTER FUNCTION meta.create_integration_table(p_name text, p_columns jsonb, p_primary_key text) OWNER TO pc_migrator;

--
-- Name: create_object(text, text, text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.create_object(p_api_name text, p_label_singular text, p_label_plural text, p_description text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_code text;
begin
  lock table meta.pc_0001 in share row exclusive mode;
  select 'pc_' || (coalesce(max(substr(object_type_id, 4)::integer), 2000) + 1)::text into v_code
  from meta.pc_0001 where object_type_id ~ '^pc_2[0-9]{3}$';
  if v_code > 'pc_2999' then
    perform meta._fail('custom object limit reached (pc_2001 to pc_2999)');
  end if;
  perform meta._create_object_table(v_code, p_api_name, p_label_singular, p_label_plural, 'custom', p_description);
  return v_code;
end $_$;


ALTER FUNCTION meta.create_object(p_api_name text, p_label_singular text, p_label_plural text, p_description text) OWNER TO pc_migrator;

--
-- Name: create_property(text, text, text, text, jsonb, text, jsonb, text, text, boolean); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.create_property(p_object text, p_api_name text, p_label text, p_type text, p_options jsonb DEFAULT '{}'::jsonb, p_description text DEFAULT NULL::text, p_dropdown_options jsonb DEFAULT '[]'::jsonb, p_calc_sql text DEFAULT NULL::text, p_calc_output_type text DEFAULT NULL::text, p_is_native boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_code text := v_obj.object_type_id;
  v_id text;
  v_deps jsonb;
  v_stmts text[];
  v_columns integer;
begin
  p_options := coalesce(p_options, '{}'::jsonb);
  perform meta._validate_property_name(v_code, p_api_name, p_label, null);
  if p_api_name is null or p_label is null then
    perform meta._fail('api_name and label are required');
  end if;
  if p_type is null or p_type not in ('text', 'number', 'dropdown', 'date', 'datetime', 'calculation', 'file') then
    perform meta._fail('type must be one of text, number, dropdown, date, datetime, calculation, file');
  end if;
  perform meta._validate_options(p_type, p_options);
  if p_type = 'calculation' and (p_calc_sql is null or p_calc_output_type is null) then
    perform meta._fail('calculations need calc_sql and calc_output_type');
  end if;
  if p_type <> 'calculation' and (p_calc_sql is not null or p_calc_output_type is not null) then
    perform meta._fail('calc_sql and calc_output_type are only for calculation properties');
  end if;
  if p_type <> 'dropdown' and coalesce(jsonb_array_length(p_dropdown_options), 0) > 0 then
    perform meta._fail('dropdown_options are only for dropdown properties');
  end if;

  -- Postgres allows 1600 columns per table, and dropped columns still count.
  select count(*) into v_columns from pg_attribute where attrelid = format('crm.%I', v_code)::regclass and attnum > 0;
  if v_columns >= 1500 then
    perform meta._fail(format('%s has reached the 1500 column limit; archive and delete unused properties, or ask support to rebuild the table', v_code), '55006');
  end if;

  if p_type = 'calculation' then
    v_deps := meta._analyze_calc(v_code, p_calc_sql, p_calc_output_type);
  end if;

  insert into meta.pc_0002 (object_type_id, api_name, label, description, type, options, calc_sql, calc_output_type, is_native, read_only)
  values (v_code, p_api_name, p_label, p_description, p_type, p_options, p_calc_sql, p_calc_output_type, p_is_native, p_type = 'calculation')
  returning pc_0002_id into v_id;

  v_stmts := array[format('alter table crm.%I add column %I %s', v_code, p_api_name, meta._column_type(p_type, p_calc_output_type))];
  execute v_stmts[1];

  if p_type = 'dropdown' then
    perform meta._insert_options(v_id, coalesce(p_dropdown_options, '[]'::jsonb));
    if coalesce((p_options ->> 'auto_append_users')::boolean, false) then
      perform meta._sync_user_options_for_property(v_id);
    end if;
  end if;
  v_stmts := v_stmts || meta._apply_property_rules(v_id);

  if p_type = 'calculation' then
    perform meta._store_calc_deps(v_id, v_deps);
    execute format('insert into meta.calc_queue (object_type_id, record_id) select %L, %I from crm.%I where record_status in (''active'', ''archived'') on conflict do nothing',
      v_code, v_code || '_id', v_code);
  else
    v_stmts := v_stmts || format('grant insert (%1$I), update (%1$I) on crm.%2$I to pc_api', p_api_name, v_code);
    execute v_stmts[cardinality(v_stmts)];
  end if;

  perform meta._refresh_views(v_code);
  perform meta._log_change('create_property', v_code, v_id,
    jsonb_strip_nulls(jsonb_build_object('api_name', p_api_name, 'label', p_label, 'type', p_type, 'options', p_options,
      'dropdown_options', p_dropdown_options, 'calc_sql', p_calc_sql, 'calc_output_type', p_calc_output_type, 'dependencies', v_deps)),
    v_stmts);
  return v_id;
end $_$;


ALTER FUNCTION meta.create_property(p_object text, p_api_name text, p_label text, p_type text, p_options jsonb, p_description text, p_dropdown_options jsonb, p_calc_sql text, p_calc_output_type text, p_is_native boolean) OWNER TO pc_migrator;

--
-- Name: delete_option(text, text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.delete_option(p_object text, p_api_name text, p_api_value text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_prop meta.pc_0002 := meta._resolve_property(v_obj.object_type_id, p_api_name);
  v_used boolean;
begin
  execute format('select exists (select 1 from crm.%I where %I @> array[%L]::text[])', v_obj.object_type_id, v_prop.api_name, p_api_value)
    into v_used;
  if v_used then
    perform meta._fail(format('option "%s" is still used by records; change them first or archive the option', p_api_value), '55006');
  end if;
  delete from meta.pc_0003 where property_id = v_prop.pc_0002_id and api_value = p_api_value;
  if not found then
    perform meta._fail(format('unknown option "%s"', p_api_value), 'P0002');
  end if;
  perform meta._apply_property_rules(v_prop.pc_0002_id);
  perform meta._log_change('delete_option', v_obj.object_type_id, v_prop.pc_0002_id,
    jsonb_build_object('api_name', v_prop.api_name, 'api_value', p_api_value));
end $$;


ALTER FUNCTION meta.delete_option(p_object text, p_api_name text, p_api_value text) OWNER TO pc_migrator;

--
-- Name: delete_property(text, text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.delete_property(p_object text, p_api_name text, p_confirm text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_prop meta.pc_0002 := meta._resolve_property(v_obj.object_type_id, p_api_name);
  v_stmt text;
begin
  if p_confirm is distinct from v_prop.api_name then
    perform meta._fail('confirm must equal the property api_name');
  end if;
  if v_prop.record_status <> 'archived' then
    perform meta._fail('archive the property before deleting it', '55006');
  end if;
  v_stmt := format('alter table crm.%I drop column %I', v_obj.object_type_id, v_prop.api_name);
  begin
    execute v_stmt;
  exception when dependent_objects_still_exist then
    perform meta._fail(format('blocked: other database objects depend on "%s": %s', v_prop.api_name, sqlerrm), '55006');
  end;
  delete from meta.pc_0002 where pc_0002_id = v_prop.pc_0002_id;
  perform meta._log_change('delete_property', v_obj.object_type_id, v_prop.pc_0002_id, to_jsonb(v_prop), array[v_stmt]);
end $$;


ALTER FUNCTION meta.delete_property(p_object text, p_api_name text, p_confirm text) OWNER TO pc_migrator;

--
-- Name: delete_record(text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.delete_record(p_object text, p_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_code text := v_obj.object_type_id;
  v_idcol text := v_obj.object_type_id || '_id';
  v_status text;
  v_sets text;
  v_line text;
  v_prev_parent text := current_setting('crm.deleting_parent', true);
begin
  execute format('select record_status from crm.%I where %I = $1 for update', v_code, v_idcol) into v_status using p_id;
  if v_status is null or v_status = 'deleted' then
    perform meta._fail(format('record %s does not exist', p_id), 'P0002');
  end if;
  if meta.is_line_parent(v_code) then
    perform set_config('crm.deleting_parent', v_code || ':' || p_id, true);
    for v_line in
      select l.pc_0020_id from crm.associations_both a join crm.pc_0020 l on l.pc_0020_id = a.other_record_id
      where a.object_type_id = v_code and a.record_id = p_id and a.other_object_type_id = 'pc_0020'
        and l.record_status in ('active', 'archived')
    loop
      perform meta.delete_record('pc_0020', v_line);
    end loop;
    perform set_config('crm.deleting_parent', coalesce(v_prev_parent, ''), true);
  end if;
  perform set_config('crm.skip_history', 'on', true);
  select string_agg(format('%I = null', api_name), ', ') into v_sets
  from meta.pc_0002 where object_type_id = v_code and not is_base;
  execute format('update crm.%I set name = null, record_status = ''deleted''%s where %I = $1', v_code, coalesce(', ' || v_sets, ''), v_idcol)
    using p_id;
  delete from crm.pc_0005 where (from_object_type = v_code and from_id = p_id) or (to_object_type = v_code and to_id = p_id);
  delete from meta.record_history where object_type_id = v_code and record_id = p_id;
  delete from meta.calc_queue where object_type_id = v_code and record_id = p_id;
  perform set_config('crm.skip_history', '', true);
  insert into meta.record_history (object_type_id, record_id, property, old_value, new_value, changed_by, source)
  values (v_code, p_id, 'record_status', null, '"deleted"'::jsonb, meta.actor(), meta.source());
end $_$;


ALTER FUNCTION meta.delete_record(p_object text, p_id text) OWNER TO pc_migrator;

--
-- Name: dissociate(text, text, text, text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.dissociate(p_from_object text, p_from_id text, p_to_object text, p_to_id text, p_label_id text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_a text := (meta._resolve_record_object(p_from_object)).object_type_id;
  v_b text := (meta._resolve_record_object(p_to_object)).object_type_id;
  v_count integer;
begin
  delete from crm.pc_0005
  where (p_label_id is null or label_id = p_label_id)
    and ((from_object_type = v_a and from_id = p_from_id and to_object_type = v_b and to_id = p_to_id)
      or (from_object_type = v_b and from_id = p_to_id and to_object_type = v_a and to_id = p_from_id));
  get diagnostics v_count = row_count;
  return v_count;
end $$;


ALTER FUNCTION meta.dissociate(p_from_object text, p_from_id text, p_to_object text, p_to_id text, p_label_id text) OWNER TO pc_migrator;

--
-- Name: enqueue_calcs(text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.enqueue_calcs(p_object text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_code text;
  v_total integer := 0;
  v_count integer;
begin
  for v_code in
    select distinct object_type_id from meta.pc_0002
    where type = 'calculation' and record_status = 'active'
      and (p_object is null or object_type_id = (meta._resolve_object(p_object)).object_type_id)
  loop
    execute format('insert into meta.calc_queue (object_type_id, record_id) select %L, %I from crm.%I where record_status in (''active'', ''archived'') on conflict do nothing',
      v_code, v_code || '_id', v_code);
    get diagnostics v_count = row_count;
    v_total := v_total + v_count;
  end loop;
  return v_total;
end $$;


ALTER FUNCTION meta.enqueue_calcs(p_object text) OWNER TO pc_migrator;

--
-- Name: has_active_admin(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.has_active_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  select exists (
    select 1 from auth.role_assignments a
    join auth.roles r on r.id = a.role_id and r.is_admin
    left join crm.associations_both t on a.team_id is not null and t.object_type_id = 'pc_0006'
      and t.record_id = a.team_id and t.other_object_type_id = 'pc_0000'
    join crm.pc_0000 u on u.pc_0000_id = coalesce(a.user_id, t.other_record_id)
      and u.record_status = 'active' and not coalesce(u.status, '{}') @> '{deactivated}'
  )
$$;


ALTER FUNCTION meta.has_active_admin() OWNER TO pc_migrator;

--
-- Name: has_no_duplicates(text[]); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.has_no_duplicates(p text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select p is null or cardinality(p) = (select count(distinct x) from unnest(p) x)
$$;


ALTER FUNCTION meta.has_no_duplicates(p text[]) OWNER TO pc_migrator;

--
-- Name: is_hex_id_array(text[]); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.is_hex_id_array(p text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  select p is null or not exists (select 1 from unnest(p) x where x is null or x !~ '^[0-9a-f]{10}$')
$_$;


ALTER FUNCTION meta.is_hex_id_array(p text[]) OWNER TO pc_migrator;

--
-- Name: is_json(text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.is_json(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
begin
  if p is null then
    return true;
  end if;
  perform p::jsonb;
  return true;
exception when others then
  return false;
end $$;


ALTER FUNCTION meta.is_json(p text) OWNER TO pc_migrator;

--
-- Name: is_line_parent(text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.is_line_parent(p_code text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  select p_code in ('pc_0012', 'pc_0022', 'pc_0023', 'pc_0024', 'pc_0025', 'pc_0026') or p_code ~ '^pc_2[0-9]{3}$'
$_$;


ALTER FUNCTION meta.is_line_parent(p_code text) OWNER TO pc_migrator;

--
-- Name: merge_records(text, text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.merge_records(p_object text, p_winner text, p_loser text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_code text := v_obj.object_type_id;
  v_idcol text := v_obj.object_type_id || '_id';
  v_winner_status text;
  v_loser_status text;
  v_sets text;
  v_name_calc boolean;
  v_assoc record;
  v_prev_source text := current_setting('crm.source', true);
begin
  if p_winner = p_loser then
    perform meta._fail('cannot merge a record into itself');
  end if;
  execute format('select record_status from crm.%I where %I = $1 for update', v_code, v_idcol) into v_winner_status using p_winner;
  execute format('select record_status from crm.%I where %I = $1 for update', v_code, v_idcol) into v_loser_status using p_loser;
  if v_winner_status is distinct from 'active' then
    perform meta._fail(format('winner %s must be an active record', p_winner), 'P0002');
  end if;
  if v_loser_status is null or v_loser_status not in ('active', 'archived') then
    perform meta._fail(format('loser %s must be an active or archived record', p_loser), 'P0002');
  end if;
  perform set_config('crm.source', 'merge', true);

  execute format('update crm.%I set record_status = ''merged'', merged_into_id = $1 where %I = $2', v_code, v_idcol) using p_winner, p_loser;
  execute format('update crm.%I set merged_into_id = $1 where merged_into_id = $2', v_code) using p_winner, p_loser;

  select string_agg(format('%1$I = coalesce(w.%1$I, l.%1$I)', api_name), ', ') into v_sets
  from meta.pc_0002
  where object_type_id = v_code and not is_base and type <> 'calculation';
  select type = 'calculation' into v_name_calc from meta.pc_0002 where object_type_id = v_code and api_name = 'name';
  execute format('update crm.%1$I w set %4$smerged_ids = w.merged_ids || l.%2$I || l.merged_ids%3$s from crm.%1$I l where w.%2$I = $1 and l.%2$I = $2',
    v_code, v_idcol, coalesce(', ' || v_sets, ''), case when v_name_calc then '' else 'name = coalesce(w.name, l.name), ' end)
    using p_winner, p_loser;
  if v_name_calc then
    insert into meta.calc_queue (object_type_id, record_id) values (v_code, p_winner) on conflict do nothing;
  end if;

  for v_assoc in select * from crm.associations_both where object_type_id = v_code and record_id = p_loser loop
    begin
      if v_assoc.side = 'from' then
        perform meta.associate(v_code, p_winner, v_assoc.other_object_type_id, v_assoc.other_record_id, v_assoc.label_id);
      else
        perform meta.associate(v_assoc.other_object_type_id, v_assoc.other_record_id, v_code, p_winner, v_assoc.label_id);
      end if;
    exception when others then
      null; -- duplicate, self-link, or a cardinality limit the winner already fills
    end;
  end loop;
  delete from crm.pc_0005 where (from_object_type = v_code and from_id = p_loser) or (to_object_type = v_code and to_id = p_loser);

  perform set_config('crm.source', coalesce(v_prev_source, ''), true);
end $_$;


ALTER FUNCTION meta.merge_records(p_object text, p_winner text, p_loser text) OWNER TO pc_migrator;

--
-- Name: normalize_phone(text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.normalize_phone(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when length(d) >= 7 then d end
  from (select regexp_replace(split_part(lower(coalesce(p, '')), 'x', 1), '[^0-9]', '', 'g') as d) s
$$;


ALTER FUNCTION meta.normalize_phone(p text) OWNER TO pc_migrator;

--
-- Name: note_mentions(text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.note_mentions(p_body text) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  select coalesce(array_agg(u.pc_0000_id order by m.ord), '{}')
  from (
    select x[1] as id, min(n) as ord
    from regexp_matches(coalesce(p_body, ''), '@\[[^\]\n]{1,100}\]\(([0-9a-f]{10})\)', 'g') with ordinality as t(x, n)
    group by x[1]
  ) m
  join crm.pc_0000 u on u.pc_0000_id = m.id and u.record_status = 'active'
$$;


ALTER FUNCTION meta.note_mentions(p_body text) OWNER TO pc_migrator;

--
-- Name: process_calc_queue(integer); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.process_calc_queue(p_limit integer DEFAULT 500) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_code text;
  v_ids text[];
  v_obj meta.pc_0001;
  v_prop meta.pc_0002;
  v_total integer := 0;
  v_prev_actor text := current_setting('crm.actor', true);
  v_prev_source text := current_setting('crm.source', true);
begin
  perform set_config('crm.actor', 'system:calculation', true);
  perform set_config('crm.source', 'calculation', true);
  for v_code in select distinct object_type_id from meta.calc_queue loop
    with picked as (
      select object_type_id, record_id from meta.calc_queue
      where object_type_id = v_code order by enqueued_at limit p_limit
      for update skip locked
    ), removed as (
      delete from meta.calc_queue q using picked
      where q.object_type_id = picked.object_type_id and q.record_id = picked.record_id
      returning q.record_id
    )
    select array_agg(record_id) into v_ids from removed;
    continue when v_ids is null;
    v_total := v_total + cardinality(v_ids);
    select * into v_obj from meta.pc_0001 where object_type_id = v_code;
    for v_prop in
      select * from meta.pc_0002
      where object_type_id = v_code and type = 'calculation' and record_status = 'active'
      order by pc_0002_id
    loop
      begin
        execute format(
          'update crm.%1$I t set %2$I = v.val from (select r.%3$I as id, (%4$s)::%5$s as val from crm.%6$I r where r.%3$I = any ($1)) v '
          'where t.%3$I = v.id and t.record_status in (''active'', ''archived'') and t.%2$I is distinct from v.val',
          v_code, v_prop.api_name, v_code || '_id', v_prop.calc_sql, meta._column_type('calculation', v_prop.calc_output_type), v_obj.api_name)
          using v_ids;
        if v_prop.calc_last_error is not null then
          update meta.pc_0002 set calc_last_error = null, calc_last_error_at = null where pc_0002_id = v_prop.pc_0002_id;
        end if;
      exception when others then
        update meta.pc_0002 set calc_last_error = left(sqlerrm, 1000), calc_last_error_at = now()
        where pc_0002_id = v_prop.pc_0002_id;
      end;
    end loop;
  end loop;
  perform set_config('crm.actor', coalesce(v_prev_actor, ''), true);
  perform set_config('crm.source', coalesce(v_prev_source, ''), true);
  return v_total;
end $_$;


ALTER FUNCTION meta.process_calc_queue(p_limit integer) OWNER TO pc_migrator;

--
-- Name: record_change_payloads(jsonb, integer, integer); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.record_change_payloads(p_changes jsonb, p_max integer DEFAULT 500, p_chunk integer DEFAULT 7500) RETURNS SETOF text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_item jsonb;
  v_batch jsonb := '[]'::jsonb;
  v_len integer := 10; -- {"c": []}
  v_item_len integer;
begin
  if p_changes is null or jsonb_array_length(p_changes) = 0 then
    return;
  end if;
  if jsonb_array_length(p_changes) > p_max then
    return next jsonb_build_object('bulk', (
      select jsonb_agg(distinct e->>0) from jsonb_array_elements(p_changes) e
    ))::text;
    return;
  end if;
  for v_item in select e from jsonb_array_elements(p_changes) e loop
    v_item_len := length(v_item::text) + 2; -- ", "
    if jsonb_array_length(v_batch) > 0 and v_len + v_item_len > p_chunk then
      return next jsonb_build_object('c', v_batch)::text;
      v_batch := '[]'::jsonb;
      v_len := 10;
    end if;
    v_batch := v_batch || jsonb_build_array(v_item);
    v_len := v_len + v_item_len;
  end loop;
  return next jsonb_build_object('c', v_batch)::text;
end $$;


ALTER FUNCTION meta.record_change_payloads(p_changes jsonb, p_max integer, p_chunk integer) OWNER TO pc_migrator;

--
-- Name: record_change_targets(jsonb); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.record_change_targets(p_changes jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(distinct x.item), '[]'::jsonb)
  from (
    select e as item from jsonb_array_elements(coalesce(p_changes, '[]'::jsonb)) e
    union
    select jsonb_build_array(a.other_object_type_id, a.other_record_id, e->2)
    from jsonb_array_elements(coalesce(p_changes, '[]'::jsonb)) e
    join crm.associations_both a on a.object_type_id = 'pc_0034' and a.record_id = e->>1
    where e->>0 = 'pc_0034'
  ) x
$$;


ALTER FUNCTION meta.record_change_targets(p_changes jsonb) OWNER TO pc_migrator;

--
-- Name: refresh_rls(text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.refresh_rls(p_code text) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  v_base text;
  v_using text;
begin
  if p_code = 'pc_0000' then
    v_using := 'rls.access() in (''all'', ''restricted'')';
  else
    if exists (select 1 from meta.pc_0002 where object_type_id = p_code and api_name = 'owner' and type = 'dropdown') then
      v_base := 'owner && (select rls.owner_ids())';
    else
      v_base := 'created_by = any ((select rls.creator_ids())::text[])';
    end if;
    v_using := format('rls.access() = ''all'' or (rls.access() = ''restricted'' and (%s or %I = any ((select rls.shared_ids(%L))::text[])))',
      v_base, p_code || '_id', p_code);
  end if;
  execute format('alter table crm.%I enable row level security', p_code);
  execute format('drop policy if exists view_reader_read on crm.%I', p_code);
  execute format('drop policy if exists everyone_else on crm.%I', p_code);
  execute format('create policy everyone_else on crm.%I using (current_user <> ''pc_view_reader'') with check (true)', p_code);
  execute format('create policy view_reader_read on crm.%I for select to pc_view_reader using (%s)', p_code, v_using);
  execute format('grant select on crm.%I to pc_view_reader', p_code);
end $$;


ALTER FUNCTION meta.refresh_rls(p_code text) OWNER TO pc_migrator;

--
-- Name: set_name_calculation(text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.set_name_calculation(p_object text, p_calc_sql text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_code text := v_obj.object_type_id;
  v_prop meta.pc_0002 := meta._resolve_property(v_obj.object_type_id, 'name');
  v_deps jsonb;
  v_stmts text[];
begin
  if p_calc_sql is null then
    if v_prop.type <> 'calculation' then
      perform meta._fail('name is already text');
    end if;
    update meta.pc_0002 set type = 'text', calc_sql = null, calc_output_type = null, calc_last_error = null,
      calc_last_error_at = null, read_only = false
    where pc_0002_id = v_prop.pc_0002_id;
    delete from meta.calc_dependencies where property_id = v_prop.pc_0002_id;
    v_stmts := array[format('grant insert (name), update (name) on crm.%I to pc_api', v_code)];
  else
    if v_prop.type = 'calculation' then
      perform meta._fail('name is already a calculation; change it with meta.update_calculation');
    end if;
    v_deps := meta._analyze_calc(v_code, p_calc_sql, 'text');
    if meta._calc_has_cycle(v_code, 'name', v_deps) then
      perform meta._fail('circular dependency: "name" would end up reading itself', '55006');
    end if;
    update meta.pc_0002 set type = 'calculation', calc_sql = p_calc_sql, calc_output_type = 'text', read_only = true
    where pc_0002_id = v_prop.pc_0002_id;
    perform meta._store_calc_deps(v_prop.pc_0002_id, v_deps);
    v_stmts := array[format('revoke insert (name), update (name) on crm.%I from pc_api', v_code)];
  end if;
  execute v_stmts[1];
  perform meta._refresh_views(v_code);
  if p_calc_sql is not null then
    perform meta.enqueue_calcs(v_code);
  end if;
  perform meta._log_change('set_name_calculation', v_code, v_prop.pc_0002_id,
    jsonb_strip_nulls(jsonb_build_object('api_name', 'name', 'calc_sql', p_calc_sql, 'previous_calc_sql', v_prop.calc_sql,
      'dependencies', v_deps)),
    v_stmts);
end $$;


ALTER FUNCTION meta.set_name_calculation(p_object text, p_calc_sql text) OWNER TO pc_migrator;

--
-- Name: set_object_aliases(text, text[]); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.set_object_aliases(p_object text, p_aliases text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_clean text[];
begin
  select coalesce(array_agg(distinct a order by a), '{}') into v_clean
  from (select lower(btrim(x)) as a from unnest(coalesce(p_aliases, '{}')) x) t where a <> '';
  if cardinality(v_clean) > 10 then
    perform meta._fail('an object can have at most 10 aliases');
  end if;
  if exists (select 1 from unnest(v_clean) a where char_length(a) > 63) then
    perform meta._fail('aliases are 1 to 63 characters');
  end if;
  update meta.pc_0001 set aliases = v_clean where object_type_id = v_obj.object_type_id;
  perform meta._log_change('set_object_aliases', v_obj.object_type_id, null,
    jsonb_build_object('aliases', v_clean, 'previous', v_obj.aliases));
end $$;


ALTER FUNCTION meta.set_object_aliases(p_object text, p_aliases text[]) OWNER TO pc_migrator;

--
-- Name: set_option_details(text, text, text, jsonb); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.set_option_details(p_object text, p_api_name text, p_api_value text, p_details jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_prop meta.pc_0002 := meta._resolve_property(v_obj.object_type_id, p_api_name);
  v_opt meta.pc_0003;
  v_key text;
  v_parent meta.pc_0002;
  v_values text[];
  v_bad text;
  v_given numeric;
  v_was_closed boolean;
  v_fixed numeric;
begin
  if v_prop.type <> 'dropdown' then
    perform meta._fail(format('"%s" is not a dropdown', p_api_name));
  end if;
  if p_details is null or jsonb_typeof(p_details) <> 'object' then
    perform meta._fail('details must be an object');
  end if;
  for v_key in select jsonb_object_keys(p_details) loop
    if v_key not in ('parent_values', 'is_closed', 'is_won', 'probability', 'color') then
      perform meta._fail(format('"%s" is not an option detail (allowed: parent_values, is_closed, is_won, probability, color)', v_key));
    end if;
  end loop;
  select * into v_opt from meta.pc_0003 where property_id = v_prop.pc_0002_id and api_value = p_api_value;
  if not found then
    perform meta._fail(format('unknown option "%s"', p_api_value), 'P0002');
  end if;
  v_was_closed := v_opt.is_closed;

  if p_details ? 'parent_values' then
    if jsonb_typeof(p_details -> 'parent_values') <> 'array' then
      perform meta._fail('parent_values must be an array of option values');
    end if;
    select coalesce(array_agg(distinct e), '{}') into v_values from jsonb_array_elements_text(p_details -> 'parent_values') e;
    if cardinality(v_values) > 0 then
      if not v_prop.options ? 'parent_property' then
        perform meta._fail(format('"%s" has no parent_property; set it with update_property first', p_api_name));
      end if;
      v_parent := meta._resolve_property(v_obj.object_type_id, v_prop.options ->> 'parent_property');
      select string_agg(v, ', ') into v_bad from unnest(v_values) v
      where not exists (select 1 from meta.pc_0003 o where o.property_id = v_parent.pc_0002_id and o.api_value = v);
      if v_bad is not null then
        perform meta._fail(format('%s has no option %s', v_parent.api_name, v_bad));
      end if;
    end if;
    v_opt.parent_values := v_values;
  end if;
  if p_details ? 'is_closed' then
    if jsonb_typeof(p_details -> 'is_closed') <> 'boolean' then perform meta._fail('is_closed must be true or false'); end if;
    v_opt.is_closed := (p_details ->> 'is_closed')::boolean;
  end if;
  if p_details ? 'is_won' then
    if jsonb_typeof(p_details -> 'is_won') <> 'boolean' then perform meta._fail('is_won must be true or false'); end if;
    v_opt.is_won := (p_details ->> 'is_won')::boolean;
    if v_opt.is_won then v_opt.is_closed := true; end if;
  end if;
  if v_opt.is_won and not v_opt.is_closed then
    perform meta._fail('a won option is always closed');
  end if;
  if p_details ? 'probability' then
    if jsonb_typeof(p_details -> 'probability') = 'null' then
      v_given := null;
    elsif jsonb_typeof(p_details -> 'probability') <> 'number' or (p_details ->> 'probability')::numeric not between 0 and 1 then
      perform meta._fail('probability must be a number from 0 to 1');
    else
      v_given := (p_details ->> 'probability')::numeric;
    end if;
  end if;
  if v_opt.is_closed then
    -- won is always 1, lost always 0; a closed option takes no other
    v_fixed := case when v_opt.is_won then 1 else 0 end;
    if p_details ? 'probability' and v_given is not null and v_given <> v_fixed then
      perform meta._fail(case when v_opt.is_won then 'a closed won option always has probability 1 (100%)'
        else 'a closed lost option always has probability 0' end);
    end if;
    v_opt.probability := v_fixed;
  elsif p_details ? 'probability' then
    v_opt.probability := v_given;
  elsif v_was_closed then
    -- reopened without a new probability: the old 100% or 0% no longer applies
    v_opt.probability := null;
  end if;
  if p_details ? 'color' then
    if jsonb_typeof(p_details -> 'color') = 'null' then
      v_opt.color := null;
    elsif jsonb_typeof(p_details -> 'color') <> 'string' or (p_details ->> 'color') !~ '^#[0-9A-Fa-f]{6}$' then
      perform meta._fail('color must be a hex colour like #3b82f6, or null for none');
    else
      v_opt.color := lower(p_details ->> 'color');
    end if;
  end if;

  update meta.pc_0003 set parent_values = v_opt.parent_values, is_closed = v_opt.is_closed, is_won = v_opt.is_won,
    probability = v_opt.probability, color = v_opt.color, row_updated_at = now()
  where pc_0003_id = v_opt.pc_0003_id;
  perform meta._log_change('set_option_details', v_obj.object_type_id, v_prop.pc_0002_id,
    jsonb_build_object('api_name', v_prop.api_name, 'api_value', p_api_value, 'details', p_details));
end $_$;


ALTER FUNCTION meta.set_option_details(p_object text, p_api_name text, p_api_value text, p_details jsonb) OWNER TO pc_migrator;

--
-- Name: set_record_status(text, text[], text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.set_record_status(p_object text, p_ids text[], p_status text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_changed text[];
  v_lines text[];
  v_prev_source text := current_setting('crm.source', true);
begin
  if p_status not in ('active', 'archived') then
    perform meta._fail('status must be active or archived');
  end if;
  execute format('with u as (update crm.%1$I set record_status = $1 where %2$I = any ($2) and record_status in (''active'', ''archived'') and record_status <> $1 returning %2$I)
                  select coalesce(array_agg(%2$I), ''{}'') from u',
    v_obj.object_type_id, v_obj.object_type_id || '_id')
    into v_changed using p_status, p_ids;

  if meta.is_line_parent(v_obj.object_type_id) and cardinality(v_changed) > 0 then
    if p_status = 'archived' then
      select coalesce(array_agg(l.pc_0020_id), '{}') into v_lines
      from crm.associations_both a join crm.pc_0020 l on l.pc_0020_id = a.other_record_id
      where a.object_type_id = v_obj.object_type_id and a.record_id = any (v_changed)
        and a.other_object_type_id = 'pc_0020' and l.record_status = 'active';
    else
      -- only lines whose latest status change was archiving along with a parent
      select coalesce(array_agg(l.pc_0020_id), '{}') into v_lines
      from crm.associations_both a join crm.pc_0020 l on l.pc_0020_id = a.other_record_id
      where a.object_type_id = v_obj.object_type_id and a.record_id = any (v_changed)
        and a.other_object_type_id = 'pc_0020' and l.record_status = 'archived'
        and (select h.source from meta.record_history h
             where h.object_type_id = 'pc_0020' and h.record_id = l.pc_0020_id and h.property = 'record_status'
             order by h.id desc limit 1) = 'parent_archived';
    end if;
    if cardinality(v_lines) > 0 then
      perform set_config('crm.source', case when p_status = 'archived' then 'parent_archived' else 'parent_restored' end, true);
      update crm.pc_0020 set record_status = p_status where pc_0020_id = any (v_lines);
      perform set_config('crm.source', coalesce(v_prev_source, ''), true);
    end if;
  end if;
  return cardinality(v_changed);
end $_$;


ALTER FUNCTION meta.set_record_status(p_object text, p_ids text[], p_status text) OWNER TO pc_migrator;

--
-- Name: set_search_properties(text, text[]); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.set_search_properties(p_object text, p_properties text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_name text;
begin
  if p_properties is null or cardinality(p_properties) = 0 or cardinality(p_properties) > 10 then
    perform meta._fail('search properties must list 1 to 10 text properties');
  end if;
  foreach v_name in array p_properties loop
    if not exists (select 1 from meta.pc_0002 where object_type_id = v_obj.object_type_id and api_name = v_name
        and type = 'text' and record_status = 'active') then
      perform meta._fail(format('"%s" is not an active text property of %s', v_name, v_obj.api_name));
    end if;
  end loop;
  update meta.pc_0001 set search_properties = p_properties where object_type_id = v_obj.object_type_id;
  perform meta._log_change('set_search_properties', v_obj.object_type_id, null,
    jsonb_build_object('search_properties', p_properties, 'previous', v_obj.search_properties));
end $$;


ALTER FUNCTION meta.set_search_properties(p_object text, p_properties text[]) OWNER TO pc_migrator;

