--
-- Name: test_calculation(text, text, text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.test_calculation(p_object text, p_calc_sql text, p_output_type text, p_record_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_idcol text := v_obj.object_type_id || '_id';
  v_deps jsonb;
  v_value text;
  v_found boolean;
  v_started timestamptz;
begin
  if p_calc_sql is null or btrim(p_calc_sql) = '' then
    perform meta._fail('calculation SQL is required');
  end if;
  execute format('select exists (select 1 from crm.%I where %I = $1)', v_obj.object_type_id, v_idcol) into v_found using p_record_id;
  if not v_found then
    perform meta._fail(format('unknown record "%s"', p_record_id), 'P0002');
  end if;
  v_deps := meta._analyze_calc(v_obj.object_type_id, p_calc_sql, p_output_type);
  v_started := clock_timestamp();
  begin
    execute format('select ((%s)::%s)::text from crm.%I r where r.%I = $1',
      p_calc_sql, meta._column_type('calculation', p_output_type), v_obj.api_name, v_idcol)
      into strict v_value using p_record_id;
  exception
    when too_many_rows then
      perform meta._fail('calculation must return exactly one row per record');
    when others then
      perform meta._fail(format('calculation fails on record %s: %s', p_record_id, sqlerrm));
  end;
  return jsonb_build_object(
    'value', v_value,
    'dependencies', v_deps,
    'ms', round(extract(epoch from clock_timestamp() - v_started)::numeric * 1000, 1)
  );
end $_$;


ALTER FUNCTION meta.test_calculation(p_object text, p_calc_sql text, p_output_type text, p_record_id text) OWNER TO pc_migrator;

--
-- Name: tg_association_accepted_lock(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.tg_association_accepted_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_row crm.pc_0005 := case when tg_op = 'DELETE' then old else new end;
  v_line text;
  v_other_type text;
  v_other text;
  v_quote text;
  v_status text;
begin
  if v_row.from_object_type = 'pc_0020' then
    v_line := v_row.from_id; v_other_type := v_row.to_object_type; v_other := v_row.to_id;
  elsif v_row.to_object_type = 'pc_0020' then
    v_line := v_row.to_id; v_other_type := v_row.from_object_type; v_other := v_row.from_id;
  else
    return v_row;
  end if;

  if v_other_type = 'pc_0022' then
    select pc_0022_id into v_quote from crm.pc_0022
    where pc_0022_id = v_other and status[1] = 'accepted' and record_status not in ('deleted', 'merged');
  elsif v_other_type = 'pc_0021' then
    v_quote := meta._line_accepted_quote(v_line);
  else
    return v_row;
  end if;
  if v_quote is null then
    return v_row;
  end if;
  if tg_op = 'DELETE' then
    select record_status into v_status from crm.pc_0020 where pc_0020_id = v_line;
    if v_status in ('deleted', 'merged') or current_setting('crm.deleting_parent', true) = 'pc_0022:' || v_quote then
      return v_row;
    end if;
  end if;
  if v_other_type = 'pc_0022' then
    perform meta._fail(format('quote %s is accepted: line items cannot be %s', v_quote,
      case when tg_op = 'DELETE' then 'removed' else 'added' end), '55006');
  else
    perform meta._fail(format('line item %s is on accepted quote %s: its product cannot be changed', v_line, v_quote), '55006');
  end if;
  return v_row;
end $$;


ALTER FUNCTION meta.tg_association_accepted_lock() OWNER TO pc_migrator;

--
-- Name: tg_association_after_write(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.tg_association_after_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_row crm.pc_0005 := case when tg_op = 'DELETE' then old else new end;
  v_value jsonb;
begin
  if coalesce(current_setting('crm.skip_history', true), '') <> 'on' then
    v_value := jsonb_build_object('association_id', v_row.pc_0005_id, 'label_id', v_row.label_id);
    insert into meta.record_history (object_type_id, record_id, property, old_value, new_value, changed_by, source)
    values
      (v_row.from_object_type, v_row.from_id, 'association',
        case when tg_op = 'DELETE' then v_value || jsonb_build_object('object_type_id', v_row.to_object_type, 'record_id', v_row.to_id) end,
        case when tg_op = 'INSERT' then v_value || jsonb_build_object('object_type_id', v_row.to_object_type, 'record_id', v_row.to_id) end,
        meta.actor(), meta.source()),
      (v_row.to_object_type, v_row.to_id, 'association',
        case when tg_op = 'DELETE' then v_value || jsonb_build_object('object_type_id', v_row.from_object_type, 'record_id', v_row.from_id) end,
        case when tg_op = 'INSERT' then v_value || jsonb_build_object('object_type_id', v_row.from_object_type, 'record_id', v_row.from_id) end,
        meta.actor(), meta.source());
  end if;
  insert into meta.calc_queue (object_type_id, record_id)
  select distinct x.o, x.i
  from (values (v_row.from_object_type, v_row.from_id), (v_row.to_object_type, v_row.to_id)) x (o, i)
  where exists (
    select 1 from meta.calc_dependencies d
    join meta.pc_0002 p on p.pc_0002_id = d.property_id and p.record_status = 'active'
    where d.rel_object = 'pc_0005' and p.object_type_id = x.o
  )
  on conflict do nothing;
  return null;
end $$;


ALTER FUNCTION meta.tg_association_after_write() OWNER TO pc_migrator;

--
-- Name: tg_association_before_insert(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.tg_association_before_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_label meta.pc_0004;
  v_status text;
  v_tmp text;
  v_count integer;
begin
  select * into v_label from meta.pc_0004 where pc_0004_id = new.label_id;
  if v_label.record_status <> 'active' then
    perform meta._fail('association label is archived');
  end if;
  if v_label.is_symmetric and new.from_id > new.to_id then
    v_tmp := new.from_id;
    new.from_id := new.to_id;
    new.to_id := v_tmp;
  end if;
  execute format('select record_status from crm.%I where %I = $1', new.from_object_type, new.from_object_type || '_id')
    into v_status using new.from_id;
  if v_status is null or v_status not in ('active', 'archived') then
    perform meta._fail(format('record %s/%s does not exist', new.from_object_type, new.from_id), 'P0002');
  end if;
  v_status := null;
  execute format('select record_status from crm.%I where %I = $1', new.to_object_type, new.to_object_type || '_id')
    into v_status using new.to_id;
  if v_status is null or v_status not in ('active', 'archived') then
    perform meta._fail(format('record %s/%s does not exist', new.to_object_type, new.to_id), 'P0002');
  end if;
  if v_label.max_to_per_from is not null then
    select count(*) into v_count from crm.pc_0005 where label_id = new.label_id and from_id = new.from_id;
    if v_count >= v_label.max_to_per_from then
      perform meta._fail(format('label "%s" allows at most %s per record', coalesce(v_label.label, 'default'), v_label.max_to_per_from));
    end if;
  end if;
  if v_label.max_from_per_to is not null then
    select count(*) into v_count from crm.pc_0005 where label_id = new.label_id and to_id = new.to_id;
    if v_count >= v_label.max_from_per_to then
      perform meta._fail(format('label "%s" allows at most %s per record', coalesce(v_label.inverse_label, v_label.label, 'default'), v_label.max_from_per_to));
    end if;
  end if;
  new.created_by := coalesce(new.created_by, meta.actor());
  return new;
end $_$;


ALTER FUNCTION meta.tg_association_before_insert() OWNER TO pc_migrator;

--
-- Name: tg_association_label_allowed(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.tg_association_label_allowed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not meta.association_allowed(new.from_object_type, new.to_object_type) then
    perform meta._fail(format('%s and %s cannot be associated',
      (select api_name from meta.pc_0001 where object_type_id = new.from_object_type),
      (select api_name from meta.pc_0001 where object_type_id = new.to_object_type)));
  end if;
  return new;
end $$;


ALTER FUNCTION meta.tg_association_label_allowed() OWNER TO pc_migrator;

--
-- Name: tg_association_line_links(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.tg_association_line_links() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_line text;
  v_other_type text;
  v_other text;
  v_existing text;
begin
  if new.from_object_type = 'pc_0020' then
    v_line := new.from_id; v_other_type := new.to_object_type; v_other := new.to_id;
  elsif new.to_object_type = 'pc_0020' then
    v_line := new.to_id; v_other_type := new.from_object_type; v_other := new.from_id;
  else
    return new;
  end if;
  -- one link at a time per line
  perform 1 from crm.pc_0020 where pc_0020_id = v_line for update;
  v_existing := meta._line_other_link(v_line, v_other_type = 'pc_0021', v_other);
  if v_existing is not null then
    perform meta._fail(format('line item %s already has %s %s; a line item has one %s',
      v_line, case when v_other_type = 'pc_0021' then 'product' else 'parent' end, v_existing,
      case when v_other_type = 'pc_0021' then 'product' else 'parent record' end));
  end if;
  return new;
end $$;


ALTER FUNCTION meta.tg_association_line_links() OWNER TO pc_migrator;

--
-- Name: tg_association_no_update(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.tg_association_no_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'associations cannot be updated; delete and re-create them' using errcode = 'feature_not_supported';
end $$;


