      where (a.from_object_type = 'pc_0034' and a.from_id = v_comment) or (a.to_object_type = 'pc_0034' and a.to_id = v_comment)) > 1 then
    raise exception 'a comment is on one record only' using errcode = 'check_violation';
  end if;
