--
-- Name: tg_document_template_guard(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.tg_document_template_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
begin
  if old.record_status = 'deleted' then
    return new;
  end if;
  if old.is_builtin[1] = 'true' then
    if new.record_status in ('deleted', 'merged') then
      perform meta._fail(format('"%s" came with the CRM and cannot be deleted; archive it instead', coalesce(old.name, old.pc_0057_id)), '55006');
    end if;
  end if;
  if new.record_status <> 'deleted' and new.is_builtin is distinct from old.is_builtin then
    perform meta._fail('"Came with the CRM" cannot be changed', '55006');
  end if;
  -- the default stays active, published and the default until another one is
  if old.record_status = 'active' and old.status[1] = 'published' and old.is_default[1] = 'true'
     and (new.record_status <> 'active' or new.status[1] is distinct from 'published' or new.is_default[1] is distinct from 'true')
     and not exists (select 1 from crm.pc_0057 t
                     where t.pc_0057_id <> old.pc_0057_id and t.record_status = 'active' and t.object[1] = old.object[1]
                       and t.status[1] = 'published' and t.is_default[1] = 'true') then
    perform meta._fail(format('"%s" is the default template for %s, and there must always be one: make another template the default first',
      coalesce(old.name, old.pc_0057_id), old.object[1]), '55006');
  end if;
  return new;
end $$;


ALTER FUNCTION meta.tg_document_template_guard() OWNER TO pc_migrator;

--
-- Name: tg_line_accepted_lock(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.tg_line_accepted_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_quote text := meta._line_accepted_quote(old.pc_0020_id);
  v_changed text[];
begin
  if v_quote is null then
    return new;
  end if;
  -- deleting the quote deletes its lines (delete_record below)
  if current_setting('crm.deleting_parent', true) = 'pc_0022:' || v_quote then
    return new;
  end if;
  select coalesce(array_agg(n.key), '{}') into v_changed
  from jsonb_each(to_jsonb(new)) n
  where n.value is distinct from to_jsonb(old) -> n.key
    and n.key not in ('updated_at', 'updated_by')
    and n.key not in (select api_name from meta.pc_0002 where object_type_id = 'pc_0020' and type = 'calculation');
  if cardinality(v_changed) = 0 then
    return new;
  end if;
  -- archiving or restoring the quote takes its lines along
  if v_changed = '{record_status}' and meta.source() in ('parent_archived', 'parent_restored') then
    return new;
  end if;
  perform meta._fail(format('line item %s is on accepted quote %s and cannot be changed', old.pc_0020_id, v_quote), '55006');
  return new;
end $$;


ALTER FUNCTION meta.tg_line_accepted_lock() OWNER TO pc_migrator;

