--
-- Name: tg_object_after_write(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.tg_object_after_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_idcol text := tg_table_name || '_id';
  v_new jsonb := to_jsonb(new);
  v_old jsonb;
  v_id text := v_new ->> v_idcol;
  v_skip text[] := array['row_updated_at', 'updated_at', 'row_created_at', 'created_by', 'updated_by', 'object_type_id', v_idcol];
  v_changed text[];
  v_history boolean := coalesce(current_setting('crm.skip_history', true), '') <> 'on';
begin
  if tg_op = 'INSERT' then
    select coalesce(array_agg(e.key), '{}') into v_changed
    from jsonb_each(v_new) e
    where e.key <> all (v_skip)
      and e.value <> 'null'::jsonb
      and not (e.key = 'record_status' and e.value = '"active"'::jsonb)
      and not (e.key = 'merged_ids' and e.value = '[]'::jsonb);
    if v_history and cardinality(v_changed) > 0 then
      insert into meta.record_history (object_type_id, record_id, property, old_value, new_value, changed_by, source)
      select tg_table_name, v_id, k, null, v_new -> k, meta.actor(), meta.source() from unnest(v_changed) k;
    end if;
    -- new records always get their own calculations computed
    if exists (select 1 from meta.pc_0002 where object_type_id = tg_table_name and type = 'calculation' and record_status = 'active') then
      insert into meta.calc_queue (object_type_id, record_id) values (tg_table_name, v_id) on conflict do nothing;
    end if;
  else
    v_old := to_jsonb(old);
    select coalesce(array_agg(e.key), '{}') into v_changed
    from jsonb_each(v_new) e
    where e.key <> all (v_skip) and e.value is distinct from v_old -> e.key;
    if v_history and cardinality(v_changed) > 0 then
      insert into meta.record_history (object_type_id, record_id, property, old_value, new_value, changed_by, source)
      select tg_table_name, v_id, k, nullif(v_old -> k, 'null'::jsonb), nullif(v_new -> k, 'null'::jsonb), meta.actor(), meta.source()
      from unnest(v_changed) k;
    end if;
  end if;
  if cardinality(v_changed) > 0 then
    perform meta._enqueue_calcs(tg_table_name, v_id, v_changed);
  end if;
  return null;
end $$;


ALTER FUNCTION meta.tg_object_after_write() OWNER TO pc_migrator;

--
-- Name: tg_object_before_write(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.tg_object_before_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_idcol text := tg_table_name || '_id';
begin
  if tg_op = 'INSERT' then
    new.object_type_id := tg_table_name;
    new.created_by := coalesce(new.created_by, meta.actor());
    new.updated_by := new.created_by;
    return new;
  end if;
  if to_jsonb(new) ->> v_idcol is distinct from to_jsonb(old) ->> v_idcol
    or new.object_type_id is distinct from old.object_type_id
    or new.row_created_at is distinct from old.row_created_at then
    raise exception 'object type, record id and row_created_at cannot be changed' using errcode = 'check_violation';
  end if;
  new.row_updated_at := now();
  new.updated_by := meta.actor();
  new.created_by := old.created_by;
  return new;
end $$;


ALTER FUNCTION meta.tg_object_before_write() OWNER TO pc_migrator;

--
-- Name: tg_quote_accepted_lock(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.tg_quote_accepted_lock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_changed text[] := '{}';
  v_labels text;
begin
  if old.status[1] is distinct from 'accepted' or old.record_status in ('deleted', 'merged')
     or new.record_status = 'deleted' then
    return new;
  end if;
  if new.amount is distinct from old.amount then v_changed := array_append(v_changed, 'amount'); end if;
  if new.currency is distinct from old.currency then v_changed := array_append(v_changed, 'currency'); end if;
  if new.expiration_date is distinct from old.expiration_date then v_changed := array_append(v_changed, 'expiration_date'); end if;
  if new.responded_at is distinct from old.responded_at then v_changed := array_append(v_changed, 'responded_at'); end if;
  if new.customer_signed_at is distinct from old.customer_signed_at then v_changed := array_append(v_changed, 'customer_signed_at'); end if;
  if cardinality(v_changed) = 0 then
    return new;
  end if;
  select string_agg(label, ', ' order by array_position(v_changed, api_name)) into v_labels
  from meta.pc_0002 where object_type_id = 'pc_0022' and api_name = any (v_changed);
  perform meta._fail(format('quote %s is accepted: %s cannot be changed', old.pc_0022_id, lower(v_labels)), '55006');
  return new;
end $$;


ALTER FUNCTION meta.tg_quote_accepted_lock() OWNER TO pc_migrator;

--
-- Name: tg_quote_signed_archive(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.tg_quote_signed_archive() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
begin
  if old.record_status = 'active' and new.record_status = 'archived'
     and (old.status[1] in ('accepted', 'pending_countersign') or old.customer_signed_at is not null)
     and current_setting('crm.super_admin', true) is distinct from 'on' then
    perform meta._fail(format('quote %s is %s: only a Super Admin can archive it', old.pc_0022_id,
      case when old.status[1] = 'accepted' then 'accepted' else 'signed' end), '42501');
  end if;
  return new;
end $$;


ALTER FUNCTION meta.tg_quote_signed_archive() OWNER TO pc_migrator;

--
-- Name: tg_record_change_notify(); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.tg_record_change_notify() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_changes jsonb;
  v_payload text;
begin
  select jsonb_agg(jsonb_build_array(d.object_type_id, d.record_id, d.changed_by))
  into v_changes
  from (select distinct n.object_type_id, n.record_id, n.changed_by from new_rows n) d;
  if v_changes is null then
    return null;
  end if;
  -- comments name the record they are on too
  if exists (select 1 from new_rows n where n.object_type_id = 'pc_0034') then
    v_changes := meta.record_change_targets(v_changes);
  end if;
  for v_payload in select meta.record_change_payloads(v_changes) loop
    perform pg_notify('record_changes', v_payload);
  end loop;
  return null;
end $$;


ALTER FUNCTION meta.tg_record_change_notify() OWNER TO pc_migrator;

