CREATE FUNCTION meta.tg_users_keep_an_admin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
begin
  if old.record_status = 'active' and not coalesce(old.status, '{}') @> '{deactivated}'
     and (tg_op = 'DELETE' or new.record_status <> 'active' or coalesce(new.status, '{}') @> '{deactivated}')
     and meta._user_has_admin_role(old.pc_0000_id)
     and not meta.has_active_admin() then
    raise exception 'cannot deactivate, archive, merge or delete the last active user with an admin role; give someone else an admin role first'
      using errcode = 'check_violation';
  end if;
  return null;
end $$;


