--
-- Name: update_option(text, text, text, text, integer, text, text); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.update_option(p_object text, p_api_name text, p_api_value text, p_label text DEFAULT NULL::text, p_display_order integer DEFAULT NULL::integer, p_description text DEFAULT NULL::text, p_record_status text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_prop meta.pc_0002 := meta._resolve_property(v_obj.object_type_id, p_api_name);
begin
  if p_label is not null and char_length(p_label) not between 1 and 63 then
    perform meta._fail('option label must be 1 to 63 characters');
  end if;
  if p_record_status is not null and p_record_status not in ('active', 'archived') then
    perform meta._fail('record_status must be active or archived');
  end if;
  update meta.pc_0003 set
    label = coalesce(p_label, label),
    display_order = coalesce(p_display_order, display_order),
    description = coalesce(p_description, description),
    record_status = coalesce(p_record_status, record_status)
  where property_id = v_prop.pc_0002_id and api_value = p_api_value;
  if not found then
    perform meta._fail(format('unknown option "%s"', p_api_value), 'P0002');
  end if;
  perform meta._log_change('update_option', v_obj.object_type_id, v_prop.pc_0002_id,
    jsonb_strip_nulls(jsonb_build_object('api_name', v_prop.api_name, 'api_value', p_api_value, 'label', p_label,
      'display_order', p_display_order, 'record_status', p_record_status)));
end $$;


ALTER FUNCTION meta.update_option(p_object text, p_api_name text, p_api_value text, p_label text, p_display_order integer, p_description text, p_record_status text) OWNER TO pc_migrator;

--
-- Name: update_property(text, text, text, text, jsonb); Type: FUNCTION; Schema: meta; Owner: pc_migrator
--

CREATE FUNCTION meta.update_property(p_object text, p_api_name text, p_label text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_options jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_obj meta.pc_0001 := meta._resolve_record_object(p_object);
  v_prop meta.pc_0002 := meta._resolve_property(v_obj.object_type_id, p_api_name);
  v_offenders text[];
  v_stmts text[] := '{}';
begin
  if v_prop.is_base and (p_options is not null) then
    perform meta._fail('options of base properties cannot be changed');
  end if;
  perform meta._validate_property_name(v_obj.object_type_id, null, p_label, v_prop.pc_0002_id);
  if p_options is not null then
    perform meta._validate_options(v_prop.type, p_options);
    if v_prop.type = 'dropdown' and coalesce((p_options ->> 'single_value')::boolean, false)
      and not coalesce((v_prop.options ->> 'single_value')::boolean, false) then
      execute format('select array(select %I from crm.%I where cardinality(%I) > 1 limit 20)', v_obj.object_type_id || '_id', v_obj.object_type_id, v_prop.api_name)
        into v_offenders;
      if cardinality(v_offenders) > 0 then
        perform meta._fail(format('cannot switch "%s" to a single value: these records have more than one: %s', v_prop.api_name, array_to_string(v_offenders, ', ')), '23514');
      end if;
    end if;
  end if;

  update meta.pc_0002 set
    label = coalesce(p_label, label),
    description = coalesce(p_description, description),
    options = coalesce(p_options, options)
  where pc_0002_id = v_prop.pc_0002_id;

  if p_options is not null then
    v_stmts := meta._apply_property_rules(v_prop.pc_0002_id);
    perform meta._refresh_views(v_obj.object_type_id);
  end if;
  perform meta._log_change('update_property', v_obj.object_type_id, v_prop.pc_0002_id,
    jsonb_strip_nulls(jsonb_build_object('api_name', v_prop.api_name, 'label', p_label, 'description', p_description,
      'options', p_options, 'previous_options', case when p_options is not null then v_prop.options end)),
    v_stmts);
end $$;


ALTER FUNCTION meta.update_property(p_object text, p_api_name text, p_label text, p_description text, p_options jsonb) OWNER TO pc_migrator;

--
-- Name: currency_to_base(numeric, text, date); Type: FUNCTION; Schema: public; Owner: pc_migrator
--

CREATE FUNCTION public.currency_to_base(p_amount numeric, p_currency text, p_on date DEFAULT NULL::date) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_from text := upper(p_currency);
  v_base text;
  v_pivot text;
  v_a numeric;
  v_b numeric;
begin
  if p_amount is null or v_from is null then return null; end if;
  select code into v_base from meta.pc_0007 where is_base;
  if v_base is null then return null; end if;
  if v_from = v_base then return p_amount; end if;

  -- a past day: the rate in effect then, through the base of that day
  if p_on is not null and p_on < (now() at time zone 'utc')::date then
    select to_code into v_pivot from meta.currency_rates where rate_date <= p_on order by rate_date desc, created_at desc limit 1;
    if v_pivot is null then
      select to_code into v_pivot from meta.currency_rates order by rate_date, created_at limit 1;
    end if;
  end if;

  if v_pivot is null then
    -- today, a day not reached yet, or no history: the current rate
    select rate_to_base into v_a from meta.pc_0007 where code = v_from and record_status = 'active' and rate_date is not null;
    return p_amount * v_a;
  end if;

  v_a := case when v_from = v_pivot then 1 else coalesce(
    (select rate from meta.currency_rates where from_code = v_from and to_code = v_pivot and rate_date <= p_on order by rate_date desc limit 1),
    (select rate from meta.currency_rates where from_code = v_from and to_code = v_pivot order by rate_date limit 1)) end;
  v_b := case when v_base = v_pivot then 1 else coalesce(
    (select rate from meta.currency_rates where from_code = v_base and to_code = v_pivot and rate_date <= p_on order by rate_date desc limit 1),
    (select rate from meta.currency_rates where from_code = v_base and to_code = v_pivot order by rate_date limit 1)) end;
  return p_amount * v_a / nullif(v_b, 0);
end $$;


ALTER FUNCTION public.currency_to_base(p_amount numeric, p_currency text, p_on date) OWNER TO pc_migrator;

--
-- Name: convert_currency(numeric, text, text, date); Type: FUNCTION; Schema: reporting; Owner: pc_migrator
--

CREATE FUNCTION reporting.convert_currency(p_amount numeric, p_from text, p_to text DEFAULT NULL::text, p_on date DEFAULT NULL::date) RETURNS numeric
    LANGUAGE sql STABLE PARALLEL SAFE
    SET search_path TO 'reporting', 'pg_catalog'
    AS $$
        select p_amount * currency_rate(p_from, p_to, p_on)
      $$;


ALTER FUNCTION reporting.convert_currency(p_amount numeric, p_from text, p_to text, p_on date) OWNER TO pc_migrator;

--
-- Name: currency_rate(text, text, date); Type: FUNCTION; Schema: reporting; Owner: pc_migrator
--

CREATE FUNCTION reporting.currency_rate(p_from text, p_to text DEFAULT NULL::text, p_on date DEFAULT NULL::date) RETURNS numeric
    LANGUAGE plpgsql STABLE PARALLEL SAFE
    SET search_path TO 'reporting', 'pg_catalog'
    AS $$
      declare
        v_from text := upper(p_from);
        v_to text;
        v_pivot text;
        v_a numeric;
        v_b numeric;
      begin
        v_to := coalesce(upper(p_to), (select code from currencies where is_base));
        if v_from is null or v_to is null then return null; end if;
        if v_from = v_to then return 1; end if;

        if p_on is not null then
          -- the base in effect that day: history rows are always written against
          -- it (on the day of a base change, the rows written last)
          select to_code into v_pivot from currency_rates where rate_date <= p_on order by rate_date desc, created_at desc limit 1;
          if v_pivot is null then
            select to_code into v_pivot from currency_rates order by rate_date, created_at limit 1;
          end if;
        end if;

        if v_pivot is null then
          -- current rates (also the fallback when there is no history yet)
          select case when is_base then 1 when rate_date is not null then rate_to_base end into v_a from currencies where code = v_from;
          select case when is_base then 1 when rate_date is not null then rate_to_base end into v_b from currencies where code = v_to;
          return v_a / nullif(v_b, 0);
        end if;

        v_a := case when v_from = v_pivot then 1 else coalesce(
          (select rate from currency_rates where from_code = v_from and to_code = v_pivot and rate_date <= p_on order by rate_date desc limit 1),
          (select rate from currency_rates where from_code = v_from and to_code = v_pivot order by rate_date limit 1)) end;
        v_b := case when v_to = v_pivot then 1 else coalesce(
          (select rate from currency_rates where from_code = v_to and to_code = v_pivot and rate_date <= p_on order by rate_date desc limit 1),
          (select rate from currency_rates where from_code = v_to and to_code = v_pivot order by rate_date limit 1)) end;
        return v_a / nullif(v_b, 0);
      end $$;


ALTER FUNCTION reporting.currency_rate(p_from text, p_to text, p_on date) OWNER TO pc_migrator;

