--
-- Name: shared_ids(text); Type: FUNCTION; Schema: rls; Owner: pc_migrator
--

CREATE FUNCTION rls.shared_ids(p_code text) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_rule record;
  v_link record;
  v_clause text;
  v_part text[];
  v_ids text[] := '{}';
begin
  if rls.access() <> 'restricted' or cardinality(rls.rule_ids()) = 0 then
    return v_ids;
  end if;
  for v_rule in
    select r.id, r.object_type_id, r.filter_groups from auth.role_sharing_rules r
    join meta.pc_0001 o on o.object_type_id = r.object_type_id and o.record_status = 'active'
    where r.id = any (rls.rule_ids())
  loop
    v_clause := meta.compile_filter_groups(v_rule.object_type_id, v_rule.filter_groups, 's');
    continue when v_clause is null;
    if v_rule.object_type_id = p_code then
      execute format('select array(select s.%I from crm.%I s where %s)', p_code || '_id', p_code, v_clause) into v_part;
      v_ids := v_ids || v_part;
    end if;
    for v_link in select label_id from auth.role_sharing_rule_associations where rule_id = v_rule.id and object_type_id = p_code loop
      execute format(
        'select array(select sa.record_id from crm.associations_both sa join crm.%1$I s on s.%2$I = sa.other_record_id
          where sa.object_type_id = $1 and sa.other_object_type_id = $2 and ($3::text is null or sa.label_id = $3)
            and s.record_status = ''active'' and %3$s)',
        v_rule.object_type_id, v_rule.object_type_id || '_id', v_clause)
      into v_part using p_code, v_rule.object_type_id, v_link.label_id;
      v_ids := v_ids || v_part;
    end loop;
  end loop;
  return v_ids;
end $_$;


ALTER FUNCTION rls.shared_ids(p_code text) OWNER TO pc_migrator;

--
-- Name: _nav_drop_view(); Type: FUNCTION; Schema: ui; Owner: pc_migrator
--

CREATE FUNCTION ui._nav_drop_view() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
begin
  -- old.slug: a permanent delete has already blanked the new row
  if old.slug is not null then
    update ui.nav_menus
    set items = ui._nav_without_view(items, old.slug),
        bottom_items = ui._nav_without_view(bottom_items, old.slug),
        updated_at = now()
    where items is distinct from ui._nav_without_view(items, old.slug)
       or bottom_items is distinct from ui._nav_without_view(bottom_items, old.slug);
  end if;
  return null;
end $$;


ALTER FUNCTION ui._nav_drop_view() OWNER TO pc_migrator;

--
-- Name: _nav_without_view(jsonb, text); Type: FUNCTION; Schema: ui; Owner: pc_migrator
--

CREATE FUNCTION ui._nav_without_view(p_items jsonb, p_slug text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(
    case when i ->> 'type' = 'section'
      then jsonb_set(i, '{items}', ui._nav_without_view(coalesce(i -> 'items', '[]'), p_slug))
      else i end
    order by n), '[]')
  from jsonb_array_elements(coalesce(p_items, '[]')) with ordinality as e(i, n)
  where not (i ->> 'type' = 'custom_view' and lower(i ->> 'slug') = lower(p_slug))
$$;


ALTER FUNCTION ui._nav_without_view(p_items jsonb, p_slug text) OWNER TO pc_migrator;

