--
-- Name: associations_both; Type: VIEW; Schema: crm; Owner: pc_migrator
--

CREATE VIEW crm.associations_both AS
 SELECT a.pc_0005_id AS association_id,
    a.label_id,
    l.label,
    a.from_object_type AS object_type_id,
    a.from_id AS record_id,
    a.to_object_type AS other_object_type_id,
    a.to_id AS other_record_id,
    'from'::text AS side,
    a.created_at
   FROM (crm.pc_0005 a
     JOIN meta.pc_0004 l ON ((l.pc_0004_id = a.label_id)))
UNION ALL
 SELECT a.pc_0005_id AS association_id,
    a.label_id,
    COALESCE(l.inverse_label, l.label) AS label,
    a.to_object_type AS object_type_id,
    a.to_id AS record_id,
    a.from_object_type AS other_object_type_id,
    a.from_id AS other_record_id,
    'to'::text AS side,
    a.created_at
   FROM (crm.pc_0005 a
     JOIN meta.pc_0004 l ON ((l.pc_0004_id = a.label_id)));


