--
-- Name: payments; Type: VIEW; Schema: crm; Owner: pc_migrator
--

CREATE VIEW crm.payments AS
 SELECT t.object_type_id,
    t.pc_0024_id,
    t.name,
    t.created_at,
    t.updated_at,
    t.merged_ids,
    t.record_status,
    t.created_by,
    t.updated_by,
    t.amount,
    t.currency[1] AS currency,
    o1.label AS currency__label,
    t.status[1] AS status,
    o2.label AS status__label,
    t.method[1] AS method,
    o3.label AS method__label,
    t.paid_at,
    t.stripe_checkout_session_id,
    t.stripe_payment_intent_id,
    t.payer_name,
    t.payer_email,
    t.reference,
    t.purpose[1] AS purpose,
    o4.label AS purpose__label
   FROM ((((crm.pc_0024 t
     LEFT JOIN meta.pc_0003 o1 ON (((o1.property_id = '00000000da'::text) AND (o1.api_value = t.currency[1]))))
     LEFT JOIN meta.pc_0003 o2 ON (((o2.property_id = '00000000db'::text) AND (o2.api_value = t.status[1]))))
     LEFT JOIN meta.pc_0003 o3 ON (((o3.property_id = '00000000dc'::text) AND (o3.api_value = t.method[1]))))
     LEFT JOIN meta.pc_0003 o4 ON (((o4.property_id = '0000000161'::text) AND (o4.api_value = t.purpose[1]))));


