    row_created_at timestamp with time zone DEFAULT now() NOT NULL,
    row_updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by text,
    updated_by text,
    task_type text[],
    status text[],
    priority text[],
    due_at timestamp with time zone,
    body text,
    owner text[],
    CONSTRAINT pc_0033_merged_into_id_check CHECK ((merged_into_id ~ '^[0-9a-f]{10}$'::text)),
