    CONSTRAINT pcc_00000000fa_shape CHECK (((cardinality(task_type) >= 1) AND meta.has_no_duplicates(task_type))),
    CONSTRAINT pcc_00000000fa_single CHECK ((cardinality(task_type) <= 1)),
    CONSTRAINT pcc_00000000fa_values CHECK ((task_type <@ '{call,email,todo}'::text[])),
    CONSTRAINT pcc_00000000fb_shape CHECK (((cardinality(status) >= 1) AND meta.has_no_duplicates(status))),
    CONSTRAINT pcc_00000000fb_single CHECK ((cardinality(status) <= 1)),
    CONSTRAINT pcc_00000000fb_values CHECK ((status <@ '{completed,in_progress,not_started,waiting}'::text[])),
    CONSTRAINT pcc_00000000fc_shape CHECK (((cardinality(priority) >= 1) AND meta.has_no_duplicates(priority))),
    CONSTRAINT pcc_00000000fc_single CHECK ((cardinality(priority) <= 1)),
    CONSTRAINT pcc_00000000fc_values CHECK ((priority <@ '{high,low,medium}'::text[])),
    CONSTRAINT pcc_00000000ff_shape CHECK (((cardinality(owner) >= 1) AND meta.has_no_duplicates(owner))),
    CONSTRAINT pcc_00000000ff_single CHECK ((cardinality(owner) <= 1)),
    CONSTRAINT pcc_00000000ff_values CHECK ((owner <@ '{}'::text[]))
);


