--
-- Name: pc_0055; Type: TABLE; Schema: crm; Owner: pc_migrator
--

CREATE TABLE crm.pc_0055 (
    object_type_id text DEFAULT 'pc_0055'::text NOT NULL,
    pc_0055_id text NOT NULL,
    name text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone GENERATED ALWAYS AS (row_updated_at) STORED,
    merged_ids text[] DEFAULT '{}'::text[] NOT NULL,
    merged_into_id text,
    record_status text DEFAULT 'active'::text NOT NULL,
    row_created_at timestamp with time zone DEFAULT now() NOT NULL,
    row_updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by text,
    updated_by text,
    description text,
    slug text,
    icon text,
    status text[] DEFAULT '{draft}'::text[],
    audience text[] DEFAULT '{admins}'::text[],
    draft_source text,
    draft_queries text,
    source text,
    queries text,
    published_at timestamp with time zone,
    allow_snippets text[],
    CONSTRAINT pc_0055_merged_into_id_check CHECK ((merged_into_id ~ '^[0-9a-f]{10}$'::text)),
    CONSTRAINT pc_0055_object_type_id_check CHECK ((object_type_id = 'pc_0055'::text)),
    CONSTRAINT pc_0055_pc_0055_id_check CHECK ((pc_0055_id ~ '^[0-9a-f]{10}$'::text)),
    CONSTRAINT pc_0055_record_status_check CHECK ((record_status = ANY (ARRAY['active'::text, 'archived'::text, 'merged'::text, 'deleted'::text]))),
    CONSTRAINT pcc_000000016c_regex CHECK ((slug ~ '^[a-z0-9](?:[a-z0-9-]{1,58}[a-z0-9])$'::text)),
    CONSTRAINT pcc_000000016c_single_line CHECK (((strpos(slug, chr(10)) = 0) AND (strpos(slug, chr(13)) = 0))),
    CONSTRAINT pcc_000000016d_regex CHECK ((icon ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text)),
    CONSTRAINT pcc_000000016d_single_line CHECK (((strpos(icon, chr(10)) = 0) AND (strpos(icon, chr(13)) = 0))),
    CONSTRAINT pcc_000000016e_required CHECK (((status IS NOT NULL) OR (record_status = 'deleted'::text))),
    CONSTRAINT pcc_000000016e_shape CHECK (((cardinality(status) >= 1) AND meta.has_no_duplicates(status))),
    CONSTRAINT pcc_000000016e_single CHECK ((cardinality(status) <= 1)),
    CONSTRAINT pcc_000000016e_values CHECK ((status <@ '{draft,published}'::text[])),
    CONSTRAINT pcc_000000016f_required CHECK (((audience IS NOT NULL) OR (record_status = 'deleted'::text))),
    CONSTRAINT pcc_000000016f_shape CHECK (((cardinality(audience) >= 1) AND meta.has_no_duplicates(audience))),
    CONSTRAINT pcc_000000016f_single CHECK ((cardinality(audience) <= 1)),
    CONSTRAINT pcc_000000016f_values CHECK ((audience <@ '{admins,everyone}'::text[])),
    CONSTRAINT pcc_0000000171_json CHECK (meta.is_json(draft_queries)),
    CONSTRAINT pcc_0000000173_json CHECK (meta.is_json(queries)),
    CONSTRAINT pcc_00000001ef_shape CHECK (((cardinality(allow_snippets) >= 1) AND meta.has_no_duplicates(allow_snippets))),
    CONSTRAINT pcc_00000001ef_single CHECK ((cardinality(allow_snippets) <= 1)),
    CONSTRAINT pcc_00000001ef_values CHECK ((allow_snippets <@ '{false,true}'::text[]))
);


