--
-- Name: products; Type: VIEW; Schema: crm; Owner: pc_migrator
--

CREATE VIEW crm.products AS
 SELECT t.object_type_id,
    t.pc_0021_id,
    t.name,
    t.created_at,
    t.updated_at,
    t.merged_ids,
    t.record_status,
    t.created_by,
    t.updated_by,
    t.sku,
    t.description,
    t.unit_price,
    t.active[1] AS active,
    o1.label AS active__label,
    t.unit_cost,
    t.uom[1] AS uom,
    o2.label AS uom__label
   FROM ((crm.pc_0021 t
     LEFT JOIN meta.pc_0003 o1 ON (((o1.property_id = '00000000ca'::text) AND (o1.api_value = t.active[1]))))
     LEFT JOIN meta.pc_0003 o2 ON (((o2.property_id = '00000001ae'::text) AND (o2.api_value = t.uom[1]))));


ALTER TABLE crm.products OWNER TO pc_migrator;

--
-- Name: quotes; Type: VIEW; Schema: crm; Owner: pc_migrator
--

CREATE VIEW crm.quotes AS
 SELECT t.object_type_id,
    t.pc_0022_id,
    t.name,
    t.created_at,
    t.updated_at,
    t.merged_ids,
    t.record_status,
    t.created_by,
    t.updated_by,
    t.status[1] AS status,
    o1.label AS status__label,
    t.expiration_date,
    t.amount,
    t.currency[1] AS currency,
    o2.label AS currency__label,
    t.public_key,
    t.responded_at,
    t.responder_name,
    t.responder_email,
    t.decline_reason,
    t.signing_fields,
    t.signed_fields,
    t.customer_signature,
    t.customer_signed_at,
    t.customer_ip,
    t.requires_countersign[1] AS requires_countersign,
    o3.label AS requires_countersign__label,
    t.countersigner_name,
    t.countersigner_signature,
    t.countersigned_at,
    t.online_payment[1] AS online_payment,
    o4.label AS online_payment__label,
    t.deposit_type[1] AS deposit_type,
    o5.label AS deposit_type__label,
    t.deposit_value,
    t.slug,
    t.amount_base
   FROM (((((crm.pc_0022 t
     LEFT JOIN meta.pc_0003 o1 ON (((o1.property_id = '00000000d0'::text) AND (o1.api_value = t.status[1]))))
     LEFT JOIN meta.pc_0003 o2 ON (((o2.property_id = '00000000d3'::text) AND (o2.api_value = t.currency[1]))))
     LEFT JOIN meta.pc_0003 o3 ON (((o3.property_id = '000000012e'::text) AND (o3.api_value = t.requires_countersign[1]))))
     LEFT JOIN meta.pc_0003 o4 ON (((o4.property_id = '0000000159'::text) AND (o4.api_value = t.online_payment[1]))))
     LEFT JOIN meta.pc_0003 o5 ON (((o5.property_id = '000000015a'::text) AND (o5.api_value = t.deposit_type[1]))));


