    t.icon,
    t.status[1] AS status,
    o1.label AS status__label,
    t.audience[1] AS audience,
    o2.label AS audience__label,
    t.draft_source,
    t.draft_queries,
    t.source,
    t.queries,
    t.published_at,
    t.allow_snippets[1] AS allow_snippets,
    o3.label AS allow_snippets__label
   FROM (((crm.pc_0055 t
     LEFT JOIN meta.pc_0003 o1 ON (((o1.property_id = '000000016e'::text) AND (o1.api_value = t.status[1]))))
     LEFT JOIN meta.pc_0003 o2 ON (((o2.property_id = '000000016f'::text) AND (o2.api_value = t.audience[1]))))
     LEFT JOIN meta.pc_0003 o3 ON (((o3.property_id = '00000001ef'::text) AND (o3.api_value = t.allow_snippets[1]))));


ALTER TABLE crm.views OWNER TO pc_migrator;

