    CONSTRAINT pc_0007_code_check CHECK ((code ~ '^[A-Z]{3}$'::text)),
    CONSTRAINT pc_0007_decimals_check CHECK (((decimals >= 0) AND (decimals <= 6))),
    CONSTRAINT pc_0007_name_check CHECK (((char_length(name) >= 1) AND (char_length(name) <= 63))),
    CONSTRAINT pc_0007_pc_0007_id_check CHECK ((pc_0007_id ~ '^[0-9a-f]{10}$'::text)),
    CONSTRAINT pc_0007_rate_source_check CHECK ((rate_source = ANY (ARRAY['manual'::text, 'provider'::text]))),
    CONSTRAINT pc_0007_rate_to_base_check CHECK ((rate_to_base > (0)::numeric)),
    CONSTRAINT pc_0007_record_status_check CHECK ((record_status = ANY (ARRAY['active'::text, 'archived'::text])))
);


