    CONSTRAINT nav_menus_items_check CHECK ((jsonb_typeof(items) = 'array'::text)),
    CONSTRAINT nav_menus_scope_check CHECK ((scope = ANY (ARRAY['default'::text, 'user'::text, 'group'::text]))),
